css:
html, body { margin: 0; height: 100%; background: var(--term-bg, #000000); color: var(--term-fg, #c0c0c0); }
#app { height: 100%; }
/* First paint (ADR 0083 and its 2026-11-07 addendum, src/boot/first-paint.ts):
 * the start page's sky, its wordmark and a loading panel where the menu
 * will appear, in the box the start page will fill (as .wc-chrome in
 * src/chrome/kit/kit.css and src/ui/ui.css), above it. The places come
 * from src/start/geometry.css, which the script inlines. */
#wc-first { position: absolute; inset: 0; z-index: 1; overflow: hidden; pointer-events: none; user-select: none; }
html.wc-phone #wc-first {
  overflow: visible;
  inset: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px)
    env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
}
#wc-first.wcf-overlay { position: fixed; inset: 0; z-index: 2147483647; background: var(--term-bg, #000); }
.wcf-loader { position: absolute; left: 50%; top: 50%; width: min(280px, calc(100% - 64px)); transform: translate(-50%, -50%); opacity: 0; }
.wcf-loader.on { opacity: 1; }
.wcf-loader .bar { position: relative; height: 2px; border-radius: 1px; overflow: hidden;
  background: rgba(222, 237, 241, 0.16); box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3); }
.wcf-loader .f { position: absolute; inset: 0; transform-origin: 0 50%; transform: scaleX(0);
  background: linear-gradient(90deg, #4c777b, #a2c4c8 70%, #deedf1); transition: transform 0.22s ease-out; }
.wcf-loader .l { margin-top: 12px; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font: italic 14px/1.2 Georgia, "Times New Roman", serif; letter-spacing: 0.02em; color: rgba(226, 236, 238, 0.78);
  text-shadow: 0 0 1px rgba(10, 6, 3, 0.95), 0 1px 1px rgba(10, 6, 3, 0.85); font-variant-numeric: tabular-nums; }
/* Over the sky: an empty outline in the menu panel's box, the line across its middle. */
.wcf-loader.wcf-panel { left: 16px; right: 16px; margin: 0 auto; width: min(var(--wc-panel-w), calc(100% - 32px));
  height: var(--wc-panel-h); transform: none; box-sizing: border-box; border-radius: 5px;
  border: 1px solid rgba(207, 226, 228, 0.2); background: rgba(14, 11, 9, 0.28);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35), 0 30px 80px -12px rgba(0, 0, 0, 0.45);
  display: flex; flex-direction: column; justify-content: center; padding: 0 48px; }
@media (prefers-reduced-motion: reduce) { .wcf-loader .f { transition: none; } }

/* WebCockpit UI: page, output pane, input pane.
 * Import once from the app entry: `import './ui/ui.css'`.
 * Every colour, the font and the cell size are custom properties on :root,
 * set from the settings by src/theme/apply.ts and src/theme/cells.ts
 * (names after Inv §10.9). Rows and the input are exactly one cell high
 * (line-height = --cell-h) so box and block glyphs tile.
 * No smooth scrolling and no CSS animations; the caret blink and the
 * banner stars are timers (intent Goal 1, Inv §10.8, ADR 0044). */

:root {
  /* Fallbacks until src/theme applies the settings. */
  --cell-h: 17px;
  --cell-w: 9px;
  --font-mono: "WebCockpit Underscore", "DejaVu Sans Mono", monospace;
  --font-size: 15px;
  --pad: 0px;
  --cell-ls: 0px;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--term-bg, #000000);
  color: var(--term-fg, #c0c0c0);
  scroll-behavior: auto;
}

body {
  box-sizing: border-box;
  padding: var(--pad);
  font-family: var(--font-mono);
  font-size: var(--font-size);
  line-height: var(--cell-h);
  font-variant-ligatures: none;
  /* Corrects the advance to exactly --cell-w (src/theme/cells.ts). */
  letter-spacing: var(--cell-ls);
}

#app {
  height: 100%;
}

/* The cockpit: output over input (stage 2 package B adds the docks). */
.wc-app {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--term-bg);
  color: var(--term-fg);
  font-family: var(--font-mono);
  font-size: var(--font-size);
  line-height: var(--cell-h);
}

/* ------------------------------------------------------------------ output */

.wc-output {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  font-family: var(--font-mono);
  font-size: var(--font-size);
  line-height: var(--cell-h);
}

.wc-scroller {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  scroll-behavior: auto;
  /* The pane pins the tail and keeps a scrolled view in place itself
     (output-pane.ts, ADR 0045); the browser must not also. */
  overflow-anchor: none;
  /* The scrollbar shows only while scrolled back. Transparent, not hidden,
     so a classic scrollbar keeps its width and the text never reflows;
     overlay scrollbars no longer flash on every programmatic scroll. */
  scrollbar-color: transparent transparent;
}

.wc-scroller.wc-scrolled {
  scrollbar-color: auto;
}

/* scrollbar-color is inherited: without a value of their own, every row
   would be restyled whenever .wc-scrolled toggles (PageUp, Esc, wheel;
   ~130 ms at 20 000 rows in Chromium). ADR 0044 rule 2. Neither element
   scrolls, so the value shows nowhere. */
.wc-rows,
.wc-partial {
  scrollbar-color: auto;
}

.wc-chunk {
  /* A chunk's rows never affect layout outside it (see output-pane.ts). */
  contain: content;
  /* Off-screen chunks are not laid out or painted: a width change re-wraps
     only the chunks near the viewport. Their height until then is the one
     last laid out, or the estimate output-pane.ts sets in
     contain-intrinsic-block-size (ADR 0045). */
  content-visibility: auto;
}

.wc-row {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  min-height: var(--cell-h);
}

/* Export comments in the log player and the HTML replay (ADR 0019). */
.wc-comment {
  color: var(--c-yellow, #ffd75f);
}

.wc-sys {
  color: var(--c-yellow);
}

/* tt++ syntax colours (src/editor/syntax.ts): the profile editor, its HELP
 * view, and `#help` rows in the game window (ADR 0037). */
.wc-syn-cmd { color: var(--c-syn-cmd); }
.wc-syn-brace { color: var(--c-syn-brace); }
.wc-syn-delim { color: var(--c-syn-delim); }
.wc-syn-var { color: var(--c-syn-var); }
.wc-syn-code { color: var(--c-syn-code); }
.wc-syn-comment { color: var(--c-body); }

/* `#help` rows: the HELP view's roles (HELP_CLS in src/editor/frame.tsx;
 * the wc-c-* classes of the chrome kit use the same tokens). */
.wc-help-group { color: var(--c-section); font-weight: bold; }
.wc-help-heading { color: var(--c-title); font-weight: bold; }
.wc-help-syntax { color: var(--c-active); font-weight: bold; }
.wc-help-text { color: var(--c-body); }
.wc-help-note { color: var(--c-hint); }
.wc-help-code { color: var(--c-item); }

/* Map room notes after the exits line (ADR 0077, MMapper's bold "Note:"
 * and italic text). */
.wc-note-label { font-weight: bold; }
.wc-note-text { font-style: italic; color: var(--c-hint); }

/* Confirmations and listings of typed commands (src/app/messages.ts,
 * ADR 0039): a profile line in the editor's colours, the state word dimmer, and
 * amber when nothing was done or something is off (not found, not open, off).
 * The tokens follow the terminal background (ADR 0041). */
.wc-msg { color: var(--c-item); }
.wc-msg-state { color: var(--c-body); }
.wc-msg-neg { color: var(--c-note); }

/* The command echo in the input colour (ADR 0034, 0035); --term-echo is a
 * root token. The input line (.wc-input-prompt, -field, -mask) uses it too. */
.wc-echo {
  color: var(--term-echo, var(--term-fg));
}

.wc-measure {
  position: absolute;
  visibility: hidden;
  white-space: pre;
  left: 0;
  top: 0;
  pointer-events: none;
}

.wc-tail-bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--cell-h);
  white-space: pre;
  overflow: hidden;
  background: var(--c-hint);
  color: var(--term-bg);
  pointer-events: none;
}

.wc-tail-bar[hidden] {
  display: none;
}

/* Split scrollback (ADR 0117, desktop): scrolled back, the scroller above
 * shrinks and the live tail shows below a divider. The divider is a TUI
 * rule across the whole pane with the scroll text set into it; it can be
 * dragged (output-pane.ts). Both lie in normal flow on the terminal
 * background (transparent, as the rows: weather shows through them). */
.wc-split-bar {
  flex: none;
  height: var(--cell-h);
  white-space: pre;
  overflow: hidden;
  color: var(--c-item);
  cursor: row-resize;
  user-select: none;
  touch-action: none;
}

/* The rule is a neutral grey like the game window's scrollbar thumb
 * (owner, 2026-11-03): light on a dark background, darker on a light one.
 * `--sf-scheme` is the background's side (ADR 0116); `color-scheme` is
 * inherited only by the bar's own few spans. */
.wc-split-bar {
  color-scheme: var(--sf-scheme, dark);
}

.wc-split-rule {
  color: light-dark(#8c8c8c, #a8a8a8);
}

.wc-split-bar:hover .wc-split-rule,
.wc-split-bar.wc-dragging .wc-split-rule {
  color: light-dark(#4a4a4a, #dadada);
}

.wc-split-bar:hover .wc-split-text,
.wc-split-bar.wc-dragging .wc-split-text {
  color: var(--c-hover);
}

/* Newest row at the bottom; what does not fit is clipped at the top. */
.wc-split-tail {
  flex: none;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
}

.wc-split-tail > * {
  flex: none;
}

.wc-split-bar[hidden],
.wc-split-tail[hidden] {
  display: none;
}

.wc-output ::selection,
.wc-input ::selection,
.wc-input-field::selection {
  background: var(--term-fg);
  color: var(--term-bg);
}

/* Style runs. Palette 0–15 via classes; 16–255 and truecolor inline. */
.wc-f0 { color: var(--ansi-0); }
.wc-f1 { color: var(--ansi-1); }
.wc-f2 { color: var(--ansi-2); }
.wc-f3 { color: var(--ansi-3); }
.wc-f4 { color: var(--ansi-4); }
.wc-f5 { color: var(--ansi-5); }
.wc-f6 { color: var(--ansi-6); }
.wc-f7 { color: var(--ansi-7); }
.wc-f8 { color: var(--ansi-8); }
.wc-f9 { color: var(--ansi-9); }
.wc-f10 { color: var(--ansi-10); }
.wc-f11 { color: var(--ansi-11); }
.wc-f12 { color: var(--ansi-12); }
.wc-f13 { color: var(--ansi-13); }
.wc-f14 { color: var(--ansi-14); }
.wc-f15 { color: var(--ansi-15); }
.wc-b0 { background: var(--ansi-0); }
.wc-b1 { background: var(--ansi-1); }
.wc-b2 { background: var(--ansi-2); }
.wc-b3 { background: var(--ansi-3); }
.wc-b4 { background: var(--ansi-4); }
.wc-b5 { background: var(--ansi-5); }
.wc-b6 { background: var(--ansi-6); }
.wc-b7 { background: var(--ansi-7); }
.wc-b8 { background: var(--ansi-8); }
.wc-b9 { background: var(--ansi-9); }
.wc-b10 { background: var(--ansi-10); }
.wc-b11 { background: var(--ansi-11); }
.wc-b12 { background: var(--ansi-12); }
.wc-b13 { background: var(--ansi-13); }
.wc-b14 { background: var(--ansi-14); }
.wc-b15 { background: var(--ansi-15); }
/* Inverse with a default colour: default bg as fg / default fg as bg. */
.wc-fd { color: var(--term-bg); }
.wc-bd { background: var(--term-fg); }
/* A background row (output-pane.ts fillBackgroundRow): the gradient is set
 * inline. .wc-fdef is the default foreground inside one that has another. */
.wc-bgrow { background-repeat: no-repeat; }
.wc-fdef { color: var(--term-fg); }
.wc-bold { font-weight: bold; }
/* Bold colours (ADR 0060): --bold-* (src/theme/apply.ts boldTokens) are the
 * plain colours unless "Bold brightens colours" is on. .wc-fbd is a bold,
 * non-inverse run in the default foreground; .wc-inv an inverse run (its fg
 * class is the swapped background, which bold never brightens). Inside a
 * background row (.wc-bgrow) the bold is the box's, the colours nested. */
.wc-bold:not(.wc-inv).wc-f0,
.wc-bgrow.wc-bold > .wc-f0 { color: var(--bold-0, var(--ansi-0)); }
.wc-bold:not(.wc-inv).wc-f1,
.wc-bgrow.wc-bold > .wc-f1 { color: var(--bold-1, var(--ansi-1)); }
.wc-bold:not(.wc-inv).wc-f2,
.wc-bgrow.wc-bold > .wc-f2 { color: var(--bold-2, var(--ansi-2)); }
.wc-bold:not(.wc-inv).wc-f3,
.wc-bgrow.wc-bold > .wc-f3 { color: var(--bold-3, var(--ansi-3)); }
.wc-bold:not(.wc-inv).wc-f4,
.wc-bgrow.wc-bold > .wc-f4 { color: var(--bold-4, var(--ansi-4)); }
.wc-bold:not(.wc-inv).wc-f5,
.wc-bgrow.wc-bold > .wc-f5 { color: var(--bold-5, var(--ansi-5)); }
.wc-bold:not(.wc-inv).wc-f6,
.wc-bgrow.wc-bold > .wc-f6 { color: var(--bold-6, var(--ansi-6)); }
.wc-bold:not(.wc-inv).wc-f7,
.wc-bgrow.wc-bold > .wc-f7 { color: var(--bold-7, var(--ansi-7)); }
.wc-fbd { color: var(--bold-fg, currentcolor); }
.wc-bgrow.wc-bold > .wc-fdef { color: var(--bold-fg-def, var(--term-fg)); }
.wc-ital { font-style: italic; }
.wc-ul { text-decoration: underline; }
/* Blink is rendered static (no animation, intent Goal 1). */
.wc-blink { text-decoration: underline dotted; }

/* ------------------------------------------------------------------- input */

.wc-input {
  display: flex;
  flex: 0 0 auto;
  height: var(--cell-h);
  font-family: var(--font-mono);
  font-size: var(--font-size);
  line-height: var(--cell-h);
  white-space: pre;
}

.wc-input-prompt {
  flex: 0 0 calc(2 * var(--cell-w));
  color: var(--term-echo, var(--term-fg));
  width: calc(2 * var(--cell-w));
}

.wc-input-wrap {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
}

.wc-input-field {
  box-sizing: border-box;
  width: 100%;
  height: var(--cell-h);
  margin: 0;
  padding: 0;
  border: 0;
  outline: none;
  border-radius: 0;
  background: transparent;
  color: var(--term-echo, var(--term-fg));
  /* The native caret cannot be a block or underline: .wc-caret replaces it. */
  caret-color: transparent;
  font: inherit;
  letter-spacing: inherit;
  line-height: var(--cell-h);
}

/* Phone (ADR 0075 §3.2): the command line is a one-row <textarea>; it
 * behaves as the <input>: one line, scrolled sideways, no grip. */
textarea.wc-input-field {
  display: block;
  resize: none;
  overflow: hidden;
  white-space: pre;
  overflow-wrap: normal;
  scrollbar-width: none;
}

/* Password mode: the real text is transparent, bullets are drawn over it.
 * Forced colours (a high contrast mode) would paint the text in a system
 * colour, selected or not, and the password could be read: the masked line
 * keeps its own colours there. The bullets' overlay follows the mode. */
.wc-input-field.wc-masked {
  color: transparent;
  forced-color-adjust: none;
}

/* A selection in the masked line (stage 53e): the selected text is never
 * painted either. The usual selection (`.wc-input-field::selection` above)
 * gives it an opaque colour, which made a selected password readable. The
 * ground is a tint, so the bullets drawn over the line stay readable on it. */
.wc-input-field.wc-masked::selection {
  color: transparent;
  forced-color-adjust: none;
  background: color-mix(in srgb, var(--term-fg) 30%, transparent);
}

.wc-input-mask {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  overflow: hidden;
  white-space: pre;
  pointer-events: none;
  color: var(--term-echo, var(--term-fg));
}

.wc-input-mask[hidden] {
  display: none;
}

/* Autosuggestion (ADR 0063): the rest of a history entry, greyed after the
 * line. Spans the field and is clipped there; JS sets text-indent to the
 * end of the line (column × cell width − scrollLeft). Colour 8 is a muted
 * grey readable on every background theme (ADR 0061). */
.wc-input-ghost {
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  overflow: hidden;
  white-space: pre;
  pointer-events: none;
  color: var(--ansi-8);
}

.wc-input-ghost[hidden] {
  display: none;
}

/* Notice indicator (src/ui/notice-indicator.ts, ADR 0025): left of the clock. */
.wc-input-notice {
  flex: 0 0 auto;
  white-space: pre;
  user-select: none;
  cursor: help;
}

.wc-input-notice[hidden] {
  display: none;
}

/* Touch only (ADR 0075): no double-tap zoom on the page (pinch zoom
 * stays), and no text inflation (iOS landscape) that would break the
 * measured cell grid. */
html.wc-touch {
  touch-action: manipulation;
  text-size-adjust: 100%;
  -webkit-text-size-adjust: 100%;
}

.wc-notice {
  margin-left: var(--cell-w);
  font-weight: bold;
}

.wc-notice-update {
  color: var(--c-yellow);
}

.wc-notice-storage {
  color: var(--c-err);
}

/* The clock strip (src/ui/clock-strip.ts): gutter + 5 cols + blank + icon. */
.wc-input-clock {
  flex: 0 0 calc(8 * var(--cell-w));
  width: calc(8 * var(--cell-w));
  white-space: pre;
  overflow: hidden;
  user-select: none;
}

.wc-clock-time {
  font-weight: bold;
}

/* Custom caret (src/ui/input-pane.ts). Positioned by JS with a translateX
 * of column × --cell-w − scrollLeft; the style comes from <html>
 * data-cursor / data-cursor-blink (src/theme/apply.ts). Block shows the
 * character under it in the background colour; blurred, a block is hollow
 * and beam/underline are hidden. */
.wc-caret {
  position: absolute;
  left: 0;
  top: 0;
  width: var(--cell-w);
  height: var(--cell-h);
  overflow: hidden;
  white-space: pre;
  pointer-events: none;
  background: var(--term-fg);
  color: var(--term-bg);
}

.wc-caret[hidden] {
  display: none;
}

:root:not([data-cursor="block"]) .wc-caret {
  color: transparent;
}

:root:not([data-cursor="block"]):not([data-cursor="underline"]) .wc-caret {
  width: max(1px, round(down, calc(var(--font-size) / 8), 1px));
}

:root[data-cursor="underline"] .wc-caret {
  top: calc(var(--cell-h) - max(1px, round(down, calc(var(--font-size) / 8), 1px)));
  height: max(1px, round(down, calc(var(--font-size) / 8), 1px));
}

.wc-caret.wc-blurred {
  background: transparent;
  color: var(--term-fg);
  box-shadow: inset 0 0 0 1px var(--term-fg);
}

:root:not([data-cursor="block"]) .wc-caret.wc-blurred {
  display: none;
}

/* Blink (ADR 0044 rule 1): src/ui/input-pane.ts toggles .wc-caret-off on
 * a 500 ms timer, two style changes a second. No CSS animation: an
 * infinite one keeps the frame loop on the vsync grid while connected. */
.wc-caret.wc-caret-off {
  visibility: hidden;
}

/* ------------------------------------------------------------------ phone */

/* Phone only (ADR 0075 §3). The app follows the visible area
 * (src/layout/phone-viewport.ts: --wc-vv-h / --wc-vv-top) and keeps out
 * of the notch and the home indicator (viewport-fit=cover, safe-area
 * insets).
 * The cockpit and the chrome measure their cell grid inside this area. */
html.wc-phone,
html.wc-phone body {
  overflow: hidden;
  overscroll-behavior: none;
}

html.wc-phone #app {
  position: fixed;
  left: 0;
  right: 0;
  top: var(--wc-vv-top, 0px);
  height: var(--wc-vv-h, 100%);
  box-sizing: border-box;
  padding:
    calc(var(--pad) + env(safe-area-inset-top, 0px))
    calc(var(--pad) + env(safe-area-inset-right, 0px))
    calc(var(--pad) + env(safe-area-inset-bottom, 0px))
    calc(var(--pad) + env(safe-area-inset-left, 0px));
}

/* The start page and the ESC menu fill the same safe area (they are
 * absolutely placed in #app, which is their containing block here). */
html.wc-phone .wc-chrome,
html.wc-phone .wc-overlay {
  position: absolute;
  inset:
    env(safe-area-inset-top, 0px)
    env(safe-area-inset-right, 0px)
    env(safe-area-inset-bottom, 0px)
    env(safe-area-inset-left, 0px);
}

/* The menu covers the whole screen on a phone (src/chrome/index.tsx). */
html.wc-phone .wc-overlay {
  background: var(--term-bg);
}

/* Phone only (ADR 0097, ADR 0099): the fullscreen button, small and faint
 * in the top right corner, above everything (start page, cockpit, menus). */
.wc-fs-btn {
  position: fixed;
  top: calc(12px + env(safe-area-inset-top, 0px));
  right: calc(12px + env(safe-area-inset-right, 0px));
  z-index: 1000;
  width: 44px;
  height: 44px;
  padding: 10px;
  border: 0;
  background: transparent;
  color: var(--c-body);
  opacity: 0.5;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.wc-fs-btn:active {
  opacity: 0.8;
}

.wc-fs-btn svg {
  display: block;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
}

/* Cockpit layout (src/layout/cockpit.ts, ADR 0012). Every box is placed
 * by JS in whole cells (--cell-w × --cell-h); nothing here sizes by font.
 * Gaps between the game pane and the docks show the page background and
 * double as resize handles; there is no visible splitter chrome. */

.wc-cockpit {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.wc-game,
.wc-input-slot {
  position: absolute;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  /* Output lines lay out only inside the game pane (spec §1.3). */
  contain: strict;
}

.wc-pane {
  position: absolute;
  overflow: hidden;
  contain: strict;
  background: var(--pane-bg, var(--term-bg));
  color: var(--term-fg);
  line-height: var(--cell-h);
}

.wc-pane[hidden] {
  display: none;
}

/* The lantern frame (ADR 0123 "Lantern pane frame"; geometry ADR 0091
 * "Frames"): a thin band of dark iron with a faint hue of the pane colour,
 * riveted L-shaped corner brackets, a small iron hood centred on the top
 * band holding the title (lit from behind), and a window lit from within
 * by the lamp: a hot spot under the hood falling off to a dark vignette.
 *
 * Tokens, on every pane (derived from `--pane-border`, `--pane-bg` and
 * `--pane-fill`, src/theme/apply.ts `paneTokens`; one formula for every
 * tint; Plain and Grey have chroma 0, so their lamp is candle light):
 *   --lamp        candle light, coloured by the tint: in oklab at L .78, the
 *                 candle (C .085 at h 70) plus the border's hue at C .06,
 *                 both weighted by `--lamp-w` (the border's chroma × 60, at
 *                 most 1): a grey border (Plain, Grey) gives the candle
 *                 alone; a tint its own hue over 40 % of the candle, so the
 *                 light is coloured but restrained (and a hue opposite the
 *                 candle, blue, is not cancelled to grey). Mixed in oklab
 *                 (a + b), so no hue wraps. Every value stays inside sRGB.
 *   --iron        L .25, C min(c × 3, .03) in the hue: the band and hood
 *   --iron-hi     L .42, C min(c × 3, .035): lit edges, brackets
 *   --iron-lo     L .14, C min(c × 3, .02): shadowed edges, rivets
 *   --frost2      the lamp at 5 %, --frost-edge at 24 %: the rims of the
 *                 frosted cards in the window (Group, Timers; a card itself
 *                 is the lamp at 8 % in one flat colour, group.css)
 *   --card-back   what a card lies on: transparent, or on a clear pane its
 *                 tint's fill at 62 % so text stays readable over the sky
 *   --window-base the window's fill under the lamp, and --window-blur its
 *                 backdrop filter (weather.css: glass)
 *   --vignette    the window's inset shadow
 * A light pane (Paper) redefines the iron as light metal and adds its own
 * tokens: see "Paper" below.
 * Nothing here animates and no backdrop filter is added (ADR 0123 "Cost"):
 * it is all static paint, repainted only when a pane is placed or its
 * theme changes. */
.wc-pane {
  --lamp-w: min(hypot(a, b) * 60, 1);
  --lamp: oklab(
    from var(--pane-border) 0.78
      calc(a / max(hypot(a, b), 0.0001) * 0.06 * var(--lamp-w) + 0.0291 * (1 - 0.6 * var(--lamp-w)))
      calc(b / max(hypot(a, b), 0.0001) * 0.06 * var(--lamp-w) + 0.0799 * (1 - 0.6 * var(--lamp-w)))
  );
  --iron: oklch(from var(--pane-border) 0.25 min(calc(c * 3), 0.03) h);
  --iron-hi: oklch(from var(--pane-border) 0.42 min(calc(c * 3), 0.035) h);
  --iron-lo: oklch(from var(--pane-border) 0.14 min(calc(c * 3), 0.02) h);
  --frost2: color-mix(in srgb, var(--lamp) 5%, transparent);
  --frost-edge: color-mix(in srgb, var(--lamp) 24%, transparent);
  --card-back: transparent;
  --window-base: var(--pane-bg, var(--term-bg));
  --vignette: rgb(0 0 0 / 0.55);
}

.wc-pane[data-clear] {
  --card-back: color-mix(in srgb, var(--pane-fill, var(--pane-bg)) 62%, transparent);
}

.wc-pane[data-framed] {
  background: transparent;
}

/* `.wc-pane-rim` (the iron) and `.wc-pane-frame` (the window and the glow)
 * cover the frame box (`--frame-l/r/top/b` from pane.ts, whole device
 * pixels of the page). */
.wc-pane-rim,
.wc-pane-frame {
  position: absolute;
  top: var(--frame-top, 2px);
  right: var(--frame-r, 2px);
  bottom: var(--frame-b, 2px);
  left: var(--frame-l, 2px);
  pointer-events: none;
  user-select: none;
}

/* The iron: clipped (pane.ts, frame.ts `frameRimPath`) to the band and the
 * hood. Its layers, top first: the four corner rivets (lit by the lamp,
 * centred in the band), the four corner brackets (brighter iron squares
 * `--frame-arm` wide, a dark hairline where they end; the clip leaves the
 * L in the band), a sheen from the top, and the iron. Opaque, so no backdrop blur (the old glass rim's four
 * blur strips are gone, ADR 0123 "Iron, not glass"). */
.wc-pane-rim {
  --rivet: radial-gradient(
    circle closest-side,
    color-mix(in srgb, var(--lamp) 70%, #fff) 0 30%,
    var(--iron-lo) 52% 74%,
    transparent 96%
  );
  --rivet-at: var(--frame-t, 5px) var(--frame-t, 5px) no-repeat;
  --arm: var(--frame-arm, 13px) var(--frame-arm, 13px) no-repeat;
  --arm-in: calc(var(--frame-arm, 13px) - var(--frame-hair, 1px)) calc(var(--frame-arm, 13px) - var(--frame-hair, 1px)) no-repeat;
  --bracket: var(--iron-hi), color-mix(in srgb, var(--iron-hi) 65%, var(--iron));
  --bracket-end: linear-gradient(rgb(0 0 0 / 0.75), rgb(0 0 0 / 0.75));
  background:
    var(--rivet) left top / var(--rivet-at),
    var(--rivet) right top / var(--rivet-at),
    var(--rivet) left bottom / var(--rivet-at),
    var(--rivet) right bottom / var(--rivet-at),
    linear-gradient(135deg, var(--bracket)) left top / var(--arm-in),
    linear-gradient(225deg, var(--bracket)) right top / var(--arm-in),
    linear-gradient(45deg, var(--bracket)) left bottom / var(--arm-in),
    linear-gradient(315deg, var(--bracket)) right bottom / var(--arm-in),
    var(--bracket-end) left top / var(--arm),
    var(--bracket-end) right top / var(--arm),
    var(--bracket-end) left bottom / var(--arm),
    var(--bracket-end) right bottom / var(--arm),
    linear-gradient(180deg, rgb(255 255 255 / 0.1), rgb(255 255 255 / 0) 30%, rgb(0 0 0 / 0.18)),
    var(--iron);
}

/* The band's outer edge: a dark hairline, a lit hairline inside it top and
 * left, a shadowed one bottom and right. */
.wc-pane-rim::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 3px;
  border: var(--frame-hair, 1px) solid rgb(0 0 0 / 0.9);
  box-shadow:
    inset var(--frame-hair, 1px) var(--frame-hair, 1px) 0 color-mix(in srgb, var(--iron-hi) 80%, transparent),
    inset calc(-1 * var(--frame-hair, 1px)) calc(-1 * var(--frame-hair, 1px)) 0 var(--iron-lo);
}

/* The inner edge: a dark hairline round the hole (frame.ts `frameSeams`),
 * stroked twice the seam width on the edge: the clip keeps the half in the
 * iron, so it is `--frame-hair` (one device px or more) wide and sharp. */
.wc-pane-seam {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.wc-pane-seam > path {
  fill: none;
  stroke-width: calc(2 * var(--frame-hair, 1px));
  stroke-linejoin: miter;
  stroke-linecap: square;
}

.wc-pane-seam > .wc-seam-dark {
  stroke: rgb(0 0 0 / 0.9);
}

.wc-pane-seam > .wc-seam-light {
  stroke: color-mix(in srgb, var(--iron-lo) 50%, #000);
}

/* The glow: a lamp-coloured shadow round the frame box. The pane's box
 * clips it (`overflow: hidden`, `contain: strict`), so it lies only in the
 * inset ring between the band and the pane's edge, never on a neighbour. */
.wc-pane[data-framed] > .wc-pane-frame {
  border-radius: 3px;
  box-shadow: 0 0 4px 1px color-mix(in srgb, var(--lamp) 26%, transparent);
}

/* The window: the hole's bounds (inside the band), clipped round the hood
 * (`--frame-window`, pane.ts). The pane's fill (`--window-base`) with the
 * lamp over it: a hot spot under the hood and a wide fall-off from the
 * upper middle; a lamp hairline on its edge and the vignette inside. The
 * light is the same in every pane, by the cell height, not the pane's
 * size. */
.wc-pane-frame::before {
  content: '';
  position: absolute;
  inset: var(--frame-t, 5px);
  clip-path: var(--frame-window, none);
  background:
    radial-gradient(38% calc(2.6 * var(--cell-h, 19px)) at 50% 0, color-mix(in srgb, var(--lamp) 16%, transparent), transparent),
    radial-gradient(120% 80% at 50% 28%, color-mix(in srgb, var(--lamp) 19%, transparent), color-mix(in srgb, var(--lamp) 6%, transparent) 55%, transparent 88%),
    var(--window-base);
  box-shadow:
    inset 0 0 0 var(--frame-hair, 1px) color-mix(in srgb, var(--lamp) 10%, transparent),
    inset 0 0 calc(1.3 * var(--cell-h, 19px)) var(--vignette);
  -webkit-backdrop-filter: var(--window-blur, none);
  backdrop-filter: var(--window-blur, none);
}

/* Borderless (ADR 0095): no iron, hood, brackets or glow; the window light
 * and a softer vignette stay, on the pane's own background (the pane's
 * fill, or with weather on its glass: weather.css), so the content still
 * reads as a lantern. A clear borderless pane has neither. */
.wc-pane:not([data-framed]) > .wc-pane-rim {
  display: none;
}

.wc-pane:not([data-framed]) > .wc-pane-frame {
  inset: 0;
}

.wc-pane:not([data-framed]) > .wc-pane-frame::before {
  inset: 0;
  clip-path: none;
  background:
    radial-gradient(38% calc(2.6 * var(--cell-h, 19px)) at 50% 0, color-mix(in srgb, var(--lamp) 16%, transparent), transparent),
    radial-gradient(120% 80% at 50% 28%, color-mix(in srgb, var(--lamp) 19%, transparent), color-mix(in srgb, var(--lamp) 6%, transparent) 55%, transparent 88%);
  box-shadow: inset 0 0 calc(var(--cell-h, 19px)) color-mix(in srgb, var(--vignette) 82%, transparent);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.wc-pane[data-clear]:not([data-framed]) > .wc-pane-frame {
  display: none;
}

/* A floating pane keeps the ring outside the band opaque in the terminal
 * background, so the game text does not peek around it. */
.wc-pane[data-framed][data-floating] {
  background: var(--term-bg);
}

/* A clear pane (`data-clear`, the glass background off, ADR 0095): no
 * fill inside and no blur, weather on or off, so what lies behind shows
 * sharp: the page, the weather, and under a float the game text and the
 * panes it covers (weather/index.ts `floatHoles` cuts no holes for it). The
 * lamp shows as a glow round the window's inner edge and a stronger halo
 * outside; the iron stays. A borderless clear pane has no background at
 * all. The content's colours follow the page (theme/apply.ts `paneTokens`:
 * `--pane-bg` is the page's). */
.wc-pane[data-clear],
.wc-pane[data-clear][data-framed][data-floating] {
  background: transparent;
}

.wc-pane[data-clear] > .wc-pane-frame::before {
  background: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow:
    inset 0 0 0 var(--frame-hair, 1px) color-mix(in srgb, var(--lamp) 22%, transparent),
    inset 0 0 calc(var(--cell-h, 19px)) color-mix(in srgb, var(--lamp) 24%, transparent);
}

.wc-pane[data-clear][data-framed] > .wc-pane-frame {
  box-shadow: 0 0 5px 1px color-mix(in srgb, var(--lamp) 36%, transparent);
}

/* The hood and its title (ADR 0123 "Title"): iron like the band, from the
 * frame's top edge to `--plate-y1` (pane.ts, frame.ts `framePlate`),
 * centred, its lower corners rounded, outlined by a dark hairline and
 * casting a soft shadow on the band and the window; a recessed rivet each
 * side of the label. The label is Cinzel Bold (bundled, src/theme/fonts.ts
 * `TITLE_FACE`) in the lamp's colour with a soft glow, as if lit from
 * behind through the hood; its size is the cell height's (`--title-px`,
 * frame.ts `titlePx`, the width pane.ts measures). Its box is trimmed to
 * the capitals (`text-box`), so they sit in the hood's middle in any font.
 * Above the content, so a pane that fills its frame (the map) does not
 * hide it. */
.wc-pane-title {
  --hood-rivet: radial-gradient(
    circle closest-side,
    var(--iron-lo) 0 52%,
    color-mix(in srgb, var(--iron-hi) 85%, transparent) 70%,
    transparent 96%
  );
  --hood-rivet-d: max(3px, calc(0.34 * var(--cell-w, 10px)));
  position: absolute;
  left: var(--plate-x0, 0px);
  top: 0;
  width: calc(var(--plate-x1, 0px) - var(--plate-x0, 0px));
  height: var(--plate-y1, 0px);
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0 0 var(--plate-r, 6px) var(--plate-r, 6px);
  background:
    var(--hood-rivet) left calc(0.62 * var(--cell-w, 10px) - var(--hood-rivet-d) / 2) top calc(50% + var(--frame-t, 5px) / 4) / var(--hood-rivet-d) var(--hood-rivet-d) no-repeat,
    var(--hood-rivet) right calc(0.62 * var(--cell-w, 10px) - var(--hood-rivet-d) / 2) top calc(50% + var(--frame-t, 5px) / 4) / var(--hood-rivet-d) var(--hood-rivet-d) no-repeat,
    linear-gradient(180deg, rgb(255 255 255 / 0.08), rgb(0 0 0 / 0.15)),
    var(--iron);
  /* The band's outer edge and lit line run on over the hood's top (the
   * clip below cuts the outline there), so the band reads unbroken. */
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 var(--iron-hi),
    0 0 0 var(--frame-hair, 1px) rgb(0 0 0 / 0.9),
    0 2px 5px rgb(0 0 0 / 0.5);
  /* Nothing above the frame's top edge (the outline and shadow there would
   * fall in the gap). */
  clip-path: inset(0 -8px -8px -8px);
  font-family: "Cinzel", Georgia, "Times New Roman", serif;
  font-size: var(--title-px, 11.75px);
  font-weight: 700;
  font-variant-ligatures: none;
  letter-spacing: 0.08em;
  line-height: 1;
  white-space: pre;
  color: color-mix(in srgb, var(--lamp) 75%, #fff);
  text-shadow:
    0 0 4px color-mix(in srgb, var(--lamp) 85%, transparent),
    0 0 10px color-mix(in srgb, var(--lamp) 45%, transparent);
  z-index: 2;
}

/* The tracking after the last letter would push the label left of centre. */
.wc-pane-title > span {
  text-box: trim-both cap alphabetic;
  margin-right: -0.08em;
}

.wc-pane-title:empty {
  display: none;
}

.wc-pane-content {
  position: absolute;
  overflow: hidden;
  white-space: pre;
}

/* The title row: drag the pane by it. Over the top content row when the
 * border is off (ADR 0012). */
.wc-pane-grip {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--cell-h);
  cursor: grab;
  z-index: 1;
}

/* A borderless script pane's top row is a soft grip (ADR 0065): the
 * cockpit starts a move from the content itself once the pointer
 * travels, so its links stay clickable. */
.wc-pane-script:not([data-framed]) > .wc-pane-grip {
  pointer-events: none;
}

/* Close cross (" × ") in the title row, one cell in from the right so the
 * corner keeps its resize handle (borderless: at the right edge, below);
 * shown while the pointer is over the pane. Above the grip and the float
 * handles.
 *
 * The look buttons (`.wc-pane-btn`, ADR 0095; cockpit.ts, pane-buttons.ts)
 * sit left of it, two cells each, `--slot` 0 next to the cross: (the Gear
 * on Map, Comm, Timers and Group, slot 3,) Colour, Border, Background from
 * the left. They share the cross's box, colour, shadow, hover accent and
 * visibility rules, so they read as one set. */
.wc-pane-close,
.wc-pane-btn {
  position: absolute;
  top: 0;
  right: var(--cell-w);
  height: var(--cell-h);
  white-space: pre;
  background: var(--pane-bg, var(--term-bg));
  color: var(--pane-border);
  cursor: pointer;
  user-select: none;
  z-index: 3;
  display: none;
}

.wc-pane-btn {
  right: calc((4 + 2 * var(--slot, 0)) * var(--cell-w));
  width: calc(2 * var(--cell-w));
  align-items: center;
  justify-content: center;
  /* The icon's size: about the cross glyph's height in the same font size. */
  --icon: 0.66em;
}

/* On a frame: no box behind it (owner feedback 12), just under the band in
 * the top-right corner, right of the hood (`titleEnd`), light with a dark
 * shadow on the lamp-lit window (on a light pane: the border colour toward
 * the text colour); the box stays three cells wide to click. */
.wc-pane[data-framed] > :is(.wc-pane-close, .wc-pane-btn) {
  top: calc(var(--frame-top, 2px) + var(--frame-t, 5px) + 1px);
  height: calc(var(--cell-h) - var(--frame-top, 2px) - var(--frame-t, 5px) - 1px);
  background: transparent;
  font-size: 0.82em;
  line-height: 1;
  color: color-mix(in srgb, oklch(from var(--pane-border) 0.94 min(calc(c * 3), 0.028) h) 70%, transparent);
  text-shadow: 0 1px 0 rgb(0 0 0 / 0.6);
}

.wc-pane[data-framed] > .wc-pane-close {
  width: calc(3 * var(--cell-w));
  text-align: center;
}

/* The icons take the cross's shadow as a drop shadow, and sit where the
 * cross's ink sits (a little below the middle of its line box). */
.wc-pane[data-framed] > .wc-pane-btn > * {
  filter: drop-shadow(0 1px 0 rgb(0 0 0 / 0.6));
  transform: translateY(0.14em);
}

.wc-pane:hover > .wc-pane-close {
  display: block;
}

.wc-pane:hover > .wc-pane-btn {
  display: flex;
}

/* Borderless (ADR 0095 rounds 1 and 3): the cross at the right edge, the
 * buttons following it, no background at all (no bar, no boxes): the
 * icons and the cross lie on the pane's text and, clear, on the weather.
 * Their ink is the pane's label shade (L 60 on a dark pane, 34 on a light
 * one, in the tint's hue; the frame colour they had nearly vanished), with
 * a soft halo in the pane's background so they stay apart from text and
 * rain under them. A borderless float gives its top-right resize corner
 * to the cross. */
.wc-pane:not([data-framed]) > :is(.wc-pane-close, .wc-pane-btn) {
  background: transparent;
  color: var(--pane-shade-label, var(--pane-border));
  text-shadow: 0 0 2px var(--pane-bg, var(--term-bg)), 0 0 1px var(--pane-bg, var(--term-bg));
}

.wc-pane:not([data-framed]) > .wc-pane-btn > * {
  filter: drop-shadow(0 0 1px var(--pane-bg, var(--term-bg)));
}

.wc-pane:not([data-framed]) > .wc-pane-close {
  right: 0;
}

.wc-pane:not([data-framed]) > .wc-pane-btn {
  right: calc((3 + 2 * var(--slot, 0)) * var(--cell-w));
}

.wc-pane > :is(.wc-pane-close, .wc-pane-btn):hover {
  color: var(--c-accent);
}

/* A pane too narrow for every button drops some, the Gear first
 * (cockpit.ts `syncLook`, pane-buttons.ts `hoverFit`); the cross always
 * stays. */
.wc-pane > .wc-pane-btn[data-drop] {
  display: none;
}

.wc-cockpit[data-shield] :is(.wc-pane-close, .wc-pane-btn) {
  display: none;
}

/* The hover set over the hood (ADR 0123 "Hood position and hover
 * buttons"): on a pane where the hood, moved left as far as it goes, still
 * reaches under the buttons (`data-hood-cover`, pane.ts `coverHood`), a
 * hover slides an iron shelf out of the hood from where the set begins
 * (`--cover-x`, frame px) to the corner bracket: the hood's iron, depth,
 * lit lip and shadow, no seam where it joins the hood, so the hood reads
 * as grown to hold them. The hood's label fades out over the cell and a
 * half before it, so no letter is cut. The buttons and
 * the cross sit on the shelf, centred on its depth like the title. At rest
 * the hood and its label show whole. */
.wc-pane[data-framed][data-hood-cover] > .wc-pane-frame::after,
.wc-pane[data-framed][data-hood-cover] > .wc-pane-frame > .wc-pane-title::after {
  content: '';
  position: absolute;
  top: 0;
  display: none;
  pointer-events: none;
}

.wc-pane[data-framed][data-hood-cover] > .wc-pane-frame::after {
  left: var(--cover-x, 0px);
  right: calc(var(--frame-arm, 13px) + var(--frame-hair, 1px));
  height: var(--plate-y1, 0px);
  border-radius: 0 0 var(--plate-r, 6px) 0;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.08), rgb(0 0 0 / 0.15)),
    var(--iron);
  /* The hood's lip, outline (not on the left: it joins the hood) and shadow. */
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 var(--iron-hi),
    0 var(--frame-hair, 1px) 0 0 rgb(0 0 0 / 0.9),
    var(--frame-hair, 1px) 0 0 0 rgb(0 0 0 / 0.9),
    0 2px 5px rgb(0 0 0 / 0.5);
  clip-path: inset(0 -8px -8px 0);
  z-index: 2;
}

/* The fade: the hood's own iron over the label, from transparent to whole
 * across a cell and a half before the shelf (title px: `--cover-x` less the hood's
 * left edge). */
.wc-pane[data-framed][data-hood-cover] > .wc-pane-frame > .wc-pane-title::after {
  left: max(0px, calc(var(--cover-x, 0px) - var(--plate-x0, 0px) - 1.5 * var(--cell-w, 10px)));
  right: 0;
  bottom: 0;
  border-radius: 0 0 var(--plate-r, 6px) 0;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.08), rgb(0 0 0 / 0.15)),
    var(--iron);
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 var(--iron-hi);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 calc(1.5 * var(--cell-w, 10px)));
  mask-image: linear-gradient(90deg, transparent, #000 calc(1.5 * var(--cell-w, 10px)));
}

.wc-cockpit:not([data-shield]) > .wc-pane[data-framed][data-hood-cover]:hover > .wc-pane-frame::after,
.wc-cockpit:not([data-shield]) > .wc-pane[data-framed][data-hood-cover]:hover > .wc-pane-frame > .wc-pane-title::after {
  display: block;
}

/* Too little of the label would be left to read (pane.ts `coverHood`):
 * it fades out whole, and the hood's left end holds only its rivet. */
.wc-cockpit:not([data-shield]) > .wc-pane[data-framed][data-hood-cover='all']:hover > .wc-pane-frame > .wc-pane-title > span {
  opacity: 0;
}

.wc-pane[data-framed][data-hood-cover] > :is(.wc-pane-close, .wc-pane-btn) {
  top: var(--frame-top, 2px);
  height: var(--plate-y1, 15px);
}

/* The cross's line box centred on the shelf, and the icons with it (no
 * nudge down to the cross's ink, which now sits in the middle). */
.wc-pane[data-framed][data-hood-cover] > .wc-pane-close {
  line-height: var(--plate-y1, 15px);
}

.wc-pane[data-framed][data-hood-cover] > .wc-pane-btn > * {
  transform: none;
}

/* ======================================================================
 * Paper: pewter and brass ("Tenn och mässing", ADR 0123 "Paper", stage
 * 40c). A light pane (`data-light`: any pane on a light page, Plain or a
 * tint, which is a pale wash of its hue there, theme/color.ts
 * `lightTintFill`; or a clear pane on a light page) has the same elements
 * as the lantern, restyled: the iron becomes light metal in the tint's hue
 * (warm brass for Plain on Paper, Orange and Red; pewter for the cool tints
 * and Grey: one formula, the hue and chroma of `--pane-border`), with dark
 * engraved lines and dark rivets; the hood is engraved (the title in dark
 * ink over a light lip); the window is parchment, lighter under the hood
 * and darkening toward its edges; no lamp glow (on paper it reads as a
 * smudge): the frame casts a small warm shadow into the gap instead.
 * Cards (group.css, timers.css) are raised paper.
 *
 * Tokens (on the pane, from `--pane-border`):
 *   --iron      the metal, L .66 C min(c × 1.15, .07)
 *   --iron-hi   its lit side, L .88 C min(c × .8, .05): brackets, rivet
 *               centres, the vs coin
 *   --iron-lo   its shadow, L .36 C min(c × .6, .04): rivet rings, card rims
 *   --engrave   the cut lines, L .24 C min(c × .5, .035) at 85 %
 *   --ink       the title's and headers' dark ink, L .3 C min(c × .9, .06)
 *   --shade     the window's edge: the hue at L .48 mixed half with an
 *               umber, at 20 %
 * Static paint only, as the dark lantern: nothing here changes per tick. */
.wc-pane[data-light] {
  --iron: oklch(from var(--pane-border) 0.66 min(calc(c * 1.15), 0.07) h);
  --iron-hi: oklch(from var(--pane-border) 0.88 min(calc(c * 0.8), 0.05) h);
  --iron-lo: oklch(from var(--pane-border) 0.36 min(calc(c * 0.6), 0.04) h);
  --engrave: oklch(from var(--pane-border) 0.24 min(calc(c * 0.5), 0.035) h / 0.85);
  --ink: oklch(from var(--pane-border) 0.3 min(calc(c * 0.9), 0.06) h);
  --shade: color-mix(in srgb, color-mix(in oklab, oklch(from var(--pane-border) 0.48 min(calc(c * 1.2), 0.07) h), #7a5a2a) 20%, transparent);
  /* The metal's sheen, shared by the hood, the shelf and the fade: bright
   * at the top, a little shade at the bottom. */
  --metal: linear-gradient(180deg, rgb(255 255 255 / 0.4), rgb(255 255 255 / 0.05) 55%, rgb(0 0 0 / 0.08)), var(--iron);
  --metal-drop: 0 1px 3px rgb(50 35 10 / 0.3);
  /* The band's engraved outer edge and its white lit line, run on over the
   * top of the hood and the shelf. */
  --hood-edge: var(--engrave);
  --hood-edge-lit: rgb(255 255 255 / 0.75);
  --frost2: rgb(0 0 0 / 0.06);
  --frost-edge: color-mix(in srgb, var(--iron-lo) 45%, transparent);
}

/* The band: dark rivets with a lit centre, brackets in the lit metal, the
 * cut where a bracket ends engraved. */
.wc-pane[data-light] > .wc-pane-rim {
  --rivet: radial-gradient(
    circle closest-side,
    color-mix(in srgb, var(--iron-hi) 70%, transparent) 0 18%,
    var(--iron-lo) 30% 58%,
    color-mix(in srgb, var(--iron-lo) 40%, transparent) 72%,
    transparent 92%
  );
  --bracket: var(--iron-hi), color-mix(in srgb, var(--iron-hi) 55%, var(--iron));
  --bracket-end: linear-gradient(var(--engrave), var(--engrave));
}

/* Its outer edge engraved, a white lit line inside it top and left. */
.wc-pane[data-light] > .wc-pane-rim::before {
  border-color: var(--engrave);
  box-shadow:
    inset var(--frame-hair, 1px) var(--frame-hair, 1px) 0 rgb(255 255 255 / 0.75),
    inset calc(-1 * var(--frame-hair, 1px)) calc(-1 * var(--frame-hair, 1px)) 0 color-mix(in srgb, var(--iron-lo) 45%, transparent);
}

.wc-pane[data-light] > .wc-pane-rim > .wc-pane-seam > :is(.wc-seam-dark, .wc-seam-light) {
  stroke: var(--engrave);
}

/* No glow: a small warm shadow in the gap (clear or not). */
.wc-pane[data-light][data-framed] > .wc-pane-frame {
  box-shadow: var(--metal-drop);
}

/* The hood: engraved metal, the title cut in dark ink with a light lip. */
.wc-pane[data-light] > .wc-pane-frame > .wc-pane-title {
  background:
    var(--hood-rivet) left calc(0.62 * var(--cell-w, 10px) - var(--hood-rivet-d) / 2) top calc(50% + var(--frame-t, 5px) / 4) / var(--hood-rivet-d) var(--hood-rivet-d) no-repeat,
    var(--hood-rivet) right calc(0.62 * var(--cell-w, 10px) - var(--hood-rivet-d) / 2) top calc(50% + var(--frame-t, 5px) / 4) / var(--hood-rivet-d) var(--hood-rivet-d) no-repeat,
    var(--metal);
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 rgb(255 255 255 / 0.7),
    0 0 0 var(--frame-hair, 1px) var(--engrave),
    var(--metal-drop);
  color: var(--ink);
  text-shadow: 0 1px 0 rgb(255 255 255 / 0.7);
}

/* The window: parchment, a pale light under the hood and over the middle,
 * an engraved shadow under the top band and the umber shade at its edges. */
.wc-pane[data-light] > .wc-pane-frame::before {
  background:
    radial-gradient(42% calc(3 * var(--cell-h, 19px)) at 50% 0, rgb(255 255 255 / 0.45), transparent),
    radial-gradient(125% 90% at 50% 35%, rgb(255 253 245 / 0.42), rgb(255 253 245 / 0.26) 60%, rgb(255 253 245 / 0.2)),
    var(--window-base);
  box-shadow:
    inset 0 var(--frame-hair, 1px) 1px color-mix(in srgb, var(--iron-lo) 35%, transparent),
    inset 0 0 calc(1.2 * var(--cell-h, 19px)) var(--shade);
}

/* Borderless: the parchment light and a softer edge shade on the pane's
 * own background. */
.wc-pane[data-light]:not([data-framed]) > .wc-pane-frame::before {
  background: radial-gradient(125% 90% at 50% 35%, rgb(255 253 245 / 0.4), rgb(255 253 245 / 0.24) 60%, rgb(255 253 245 / 0.18));
  box-shadow: inset 0 0 calc(1.2 * var(--cell-h, 19px)) color-mix(in srgb, var(--shade) 80%, transparent);
}

/* Clear: no fill, the shade alone round the inner edge. */
.wc-pane[data-light][data-clear] > .wc-pane-frame::before {
  background: none;
  box-shadow:
    inset 0 var(--frame-hair, 1px) 1px color-mix(in srgb, var(--iron-lo) 35%, transparent),
    inset 0 0 calc(0.8 * var(--cell-h, 19px)) color-mix(in srgb, var(--shade) 70%, transparent);
}

/* The hover set: dark ink with a light lip (on the parchment under the band,
 * or on the shelf); the accent on hover as on a dark pane. */
.wc-pane[data-framed][data-light] > :is(.wc-pane-close, .wc-pane-btn) {
  color: color-mix(in srgb, var(--ink) 80%, transparent);
  text-shadow: 0 1px 0 rgb(255 255 255 / 0.6);
}

.wc-pane[data-framed][data-light] > .wc-pane-btn > * {
  filter: drop-shadow(0 1px 0 rgb(255 255 255 / 0.6));
}

.wc-pane[data-framed][data-light] > :is(.wc-pane-close, .wc-pane-btn):hover {
  color: var(--c-accent);
}

/* On the shelf the ink is whole: the metal is darker than the parchment. */
.wc-pane[data-framed][data-light][data-hood-cover] > :is(.wc-pane-close, .wc-pane-btn):not(:hover, [data-open]) {
  color: var(--ink);
}

/* The shelf and the fade over the label: the hood's metal, lip, engraved
 * outline (not on the shelf's left: it joins the hood) and shadow. */
.wc-pane[data-framed][data-light][data-hood-cover] > .wc-pane-frame::after {
  background: var(--metal);
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 rgb(255 255 255 / 0.7),
    0 var(--frame-hair, 1px) 0 0 var(--engrave),
    var(--frame-hair, 1px) 0 0 0 var(--engrave),
    var(--metal-drop);
}

.wc-pane[data-framed][data-light][data-hood-cover] > .wc-pane-frame > .wc-pane-title::after {
  background: var(--metal);
  box-shadow:
    inset 0 var(--frame-hair, 1px) 0 var(--hood-edge, rgb(0 0 0 / 0.9)),
    inset 0 calc(2 * var(--frame-hair, 1px)) 0 var(--hood-edge-lit, color-mix(in srgb, var(--iron-hi) 80%, transparent)),
    inset 0 calc(-1 * var(--frame-hair, 1px)) 0 rgb(255 255 255 / 0.7);
}

/* The Gear whose settings popup is open (ADR 0107, `Cockpit.markGear`):
 * lit in the hover accent while it shows, on every pane look. */
.wc-cockpit .wc-pane > .wc-pane-btn.wc-pane-btn-gear[data-open] {
  color: var(--c-accent);
}

/* The icons (pane-buttons.ts `LOOK_ICONS`, `GEAR_ICON`). Border off and
 * the glass background's sheen: the same ink, dimmed. */
.wc-pane-btn > svg {
  width: var(--icon);
  height: var(--icon);
  overflow: visible;
}

.wc-pane-btn-border:not([data-on]) > svg {
  opacity: 0.4;
}

.wc-pane-btn-glass > svg > .wc-look-glass {
  fill-opacity: 0.72;
}

.wc-pane-btn-glass[data-on] > svg > .wc-look-clear,
.wc-pane-btn-glass:not([data-on]) > svg > .wc-look-glass {
  display: none;
}

/* Colour: a muted colour wheel (fixed lightness and chroma, so no hue
 * shouts) round a dot in the pane's tint (`--pane-border` lifted to the
 * wheel's lightness; Plain's chroma 0 stays a neutral grey), a hairline
 * gap between them. Dimmed with the cross's 70 %; on hover, full and a
 * little stronger. */
.wc-look-wheel {
  --wheel-l: 0.74;
  --wheel-c: 0.075;
  width: var(--icon);
  height: var(--icon);
  border-radius: 50%;
  opacity: 0.8;
  background:
    radial-gradient(circle closest-side, oklch(from var(--pane-border) var(--wheel-l) min(calc(c * 8), 0.12) h) 0 44%, transparent 45%),
    conic-gradient(
      oklch(var(--wheel-l) var(--wheel-c) 25),
      oklch(var(--wheel-l) var(--wheel-c) 85),
      oklch(var(--wheel-l) var(--wheel-c) 145),
      oklch(var(--wheel-l) var(--wheel-c) 205),
      oklch(var(--wheel-l) var(--wheel-c) 265),
      oklch(var(--wheel-l) var(--wheel-c) 325),
      oklch(var(--wheel-l) var(--wheel-c) 25)
    );
  -webkit-mask: radial-gradient(circle closest-side, #000 0 44%, transparent 46% 58%, #000 60% 97%, transparent 100%);
  mask: radial-gradient(circle closest-side, #000 0 44%, transparent 46% 58%, #000 60% 97%, transparent 100%);
}

:root[data-light] .wc-look-wheel,
.wc-pane[data-light] .wc-look-wheel {
  --wheel-l: 0.62;
  --wheel-c: 0.09;
}

/* Borderless, the icons are in the label shade (round 3): the wheel a
 * little under its full strength, as framed. */
.wc-pane:not([data-framed]) .wc-look-wheel {
  opacity: 0.75;
}

.wc-pane > .wc-pane-btn-color:hover > .wc-look-wheel {
  opacity: 1;
  --wheel-c: 0.11;
}

/* A script pane shows the cross on hover like a built-in pane, framed or
 * not, over whatever its top row holds (ADR 0084 addendum). A pane made
 * with `createPane{cross = false}` is marked
 * `data-no-cross` and shows none, nor the look buttons (ADR 0095);
 * Options → Panes, pane:hide() or the script's own command turn it off.
 * Temporary panes always have the cross and never the buttons. */
.wc-pane.wc-pane-script[data-no-cross] > :is(.wc-pane-close, .wc-pane-btn) {
  display: none;
}

/* Hovering a borderless pane outlines it (ADR 0084): without a frame, on
 * the terminal background, it is hard to see where it ends. One pixel,
 * inside the pane (no layout shift), over its content, in the main window
 * background a step lighter (darker on a light one): `--pane-outline`,
 * src/theme/apply.ts. Pointer devices only, not on a phone, not while a
 * drag is on. The map and a script pane made with
 * `createPane{outline = false}` are marked
 * `data-no-outline` and get none (addendum 2). */
@media (hover: hover) {
  .wc-cockpit:not([data-phone-game]) > .wc-pane:not([data-framed]):not([data-no-outline]):hover::after {
    content: '';
    position: absolute;
    inset: 0;
    box-shadow: inset 0 0 0 1px var(--pane-outline, var(--pane-border));
    pointer-events: none;
    z-index: 4;
  }

  .wc-cockpit[data-shield] > .wc-pane:hover::after {
    content: none;
  }
}

.wc-pane[data-dragging] {
  opacity: 0.5;
}

/* A veil under a see-through or clear float (float-holes.ts, ADR 0135;
 * Firefox when its compositor is slow): hides the game text and the input
 * line there, as a hole in them would, in the page colour. Above them and
 * below every pane by document order (no z-index). */
.wc-float-veil {
  position: absolute;
  pointer-events: none;
  background: var(--term-bg);
}

/* Floating panes (ADR 0014): stacked by inline z-index from 10 up, over
 * the game pane, the docks and their resize handles. The pane fill is
 * opaque (the "Plain" tint is the terminal background), so nothing behind
 * shows through. Resize handles along the edges and corners, above the
 * title-row grip; hidden while the pane is docked. */
.wc-float-handle {
  position: absolute;
  z-index: 2;
  display: none;
}

.wc-pane[data-floating] > .wc-float-handle {
  display: block;
}

.wc-float-handle[data-edge="n"] { left: 0; right: 0; top: 0; height: max(3px, calc(var(--cell-h) * 0.25)); cursor: ns-resize; }
.wc-float-handle[data-edge="s"] { left: 0; right: 0; bottom: 0; height: max(4px, calc(var(--cell-h) * 0.4)); cursor: ns-resize; }
.wc-float-handle[data-edge="w"] { top: 0; bottom: 0; left: 0; width: max(3px, calc(var(--cell-w) * 0.4)); cursor: ew-resize; }
.wc-float-handle[data-edge="e"] { top: 0; bottom: 0; right: 0; width: max(3px, calc(var(--cell-w) * 0.4)); cursor: ew-resize; }
.wc-float-handle[data-edge="nw"] { left: 0; top: 0; width: var(--cell-w); height: var(--cell-h); cursor: nwse-resize; }
.wc-float-handle[data-edge="ne"] { right: 0; top: 0; width: var(--cell-w); height: var(--cell-h); cursor: nesw-resize; }
.wc-float-handle[data-edge="sw"] { left: 0; bottom: 0; width: var(--cell-w); height: var(--cell-h); cursor: nesw-resize; }
.wc-float-handle[data-edge="se"] { right: 0; bottom: 0; width: var(--cell-w); height: var(--cell-h); cursor: nwse-resize; }

/* A framed float: the side and bottom bands take the whole border cell, so
 * the drawn line itself (mid-cell) grabs. The top stays thin: the title row
 * below it is the move grip. */
.wc-pane[data-floating][data-framed] > .wc-float-handle[data-edge="s"] { height: var(--cell-h); }
.wc-pane[data-floating][data-framed] > .wc-float-handle:is([data-edge="e"], [data-edge="w"]) { width: var(--cell-w); }

/* A borderless float (a 1-row bar, ADR 0065): thin edge bands and small
 * corners, so its cells stay clickable. */
.wc-pane[data-floating]:not([data-framed]) > .wc-float-handle[data-edge="n"],
.wc-pane[data-floating]:not([data-framed]) > .wc-float-handle[data-edge="s"] { height: 3px; }
.wc-pane[data-floating]:not([data-framed]) > .wc-float-handle[data-edge="e"],
.wc-pane[data-floating]:not([data-framed]) > .wc-float-handle[data-edge="w"] { width: 3px; }
.wc-pane[data-floating]:not([data-framed]) > .wc-float-handle:is([data-edge="nw"], [data-edge="ne"], [data-edge="sw"], [data-edge="se"]) {
  width: 6px;
  height: 6px;
}

.wc-handles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}

.wc-handle {
  position: absolute;
  pointer-events: auto;
}

.wc-handle[data-axis="x"] {
  cursor: col-resize;
}

.wc-handle[data-axis="y"] {
  cursor: row-resize;
}

.wc-drop-bar {
  position: absolute;
  z-index: 100;
  pointer-events: none;
  background: var(--c-accent);
}

/* Where a pane dropped over the game area will float. */
.wc-drop-ghost {
  position: absolute;
  z-index: 100;
  pointer-events: none;
  box-sizing: border-box;
  border: 2px solid var(--c-accent);
}

/* The box a pane dropped into a dock's spans gets (ADR 0067). */
.wc-drop-ghost[data-span] {
  border-style: dashed;
}

.wc-drop-bar[hidden],
.wc-drop-ghost[hidden] {
  display: none;
}

/* Drag cursor (cockpit.ts `shieldEl`): a transparent cover over the
 * cockpit while a drag runs. Only this element restyles at a drag start
 * or end; a `.wc-cockpit[data-drag] *` rule would restyle every output
 * row (ADR 0044 rule 2). */
.wc-drag-shield {
  position: absolute;
  inset: 0;
  z-index: 300;
  user-select: none;
}

.wc-drag-shield[hidden] {
  display: none;
}

.wc-drag-shield[data-drag="move"] { cursor: grabbing; }
.wc-drag-shield[data-drag="x"] { cursor: col-resize; }
.wc-drag-shield[data-drag="y"] { cursor: row-resize; }
.wc-drag-shield[data-drag="n"], .wc-drag-shield[data-drag="s"] { cursor: ns-resize; }
.wc-drag-shield[data-drag="e"], .wc-drag-shield[data-drag="w"] { cursor: ew-resize; }
.wc-drag-shield[data-drag="nw"], .wc-drag-shield[data-drag="se"] { cursor: nwse-resize; }
.wc-drag-shield[data-drag="ne"], .wc-drag-shield[data-drag="sw"] { cursor: nesw-resize; }

/* Below 60 × 18 cells this replaces the view (Inv §2.1). */
.wc-too-small {
  position: absolute;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: pre-wrap;
  color: var(--c-body);
  background: var(--term-bg);
}

.wc-too-small[hidden] {
  display: none;
}

.wc-cockpit[data-too-small] > :not(.wc-too-small) {
  visibility: hidden;
}

/* Touch only (ADR 0075): a drag on a grip or a resize handle moves the
 * pane instead of scrolling the page. */
.wc-touch .wc-pane-grip,
.wc-touch .wc-float-handle {
  touch-action: none;
}

/* Pane content rows (src/panes/grid.ts): one cell high, whole cells wide. */
.wc-prow {
  height: var(--cell-h);
  line-height: var(--cell-h);
  white-space: pre;
  overflow: hidden;
}

/* Sideways only, so box lines and blocks join across rows (as .wc-line,
 * src/chrome/kit/kit.css; ADR 0049 "Clipped rows"). */
@supports (overflow: clip) {
  .wc-prow {
    overflow-x: clip;
    overflow-y: visible;
  }
}

/* Comm and UI message panes (src/panes/comm.ts, ui.ts, anchored-list.ts). */

.wc-msgpane {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  white-space: pre;
}

/* Native pixel scrolling, the browser's bar hidden (ADR 0052). The stack's
 * auto top margin keeps a short list at the bottom; scroll anchoring is
 * off, the list keeps its view itself (anchored-list.ts). */
.wc-alist {
  position: relative;
  flex: 1 1 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  overflow-anchor: none;
  scrollbar-width: none;
}

.wc-alist::-webkit-scrollbar {
  display: none;
}

.wc-alist-stack {
  flex: none;
  margin-top: auto;
}

/* One message: CSS wraps it inside the pane's whole-cell width. */
.wc-alist-stack > div {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.wc-alist-more {
  flex: none;
  height: var(--cell-h);
  overflow: hidden;
  color: #d4a04e;
  font-style: italic;
  cursor: pointer;
  user-select: none;
}

.wc-alist-more[hidden] {
  display: none;
}

/* Comm header: one row of channel cells, flush left. The cells sit above
 * the pane's title-row grip when the border is off, so clicks reach them. */
.wc-comm-header {
  flex: none;
  height: var(--cell-h);
  overflow: hidden;
  user-select: none;
}

.wc-comm-header[hidden] {
  display: none;
}

.wc-comm-cell {
  position: relative;
  z-index: 2;
  cursor: pointer;
}

.wc-ui-row {
  font-weight: bold;
}

/* Map pane (src/panes/map.ts, ADR 0020): the worker draws into the
 * canvas; the map background shows until the first frame. `--map-bg` is
 * the Options → Mapper setting (ADR 0085), MMapper's #2e3436 by default;
 * `transparent` for Transparent, so the pane's fill (or the weather behind
 * a see-through pane) shows through the map's empty space. */
.wc-map {
  background: var(--map-bg, #2e3436);
}

.wc-map-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

.wc-map-canvas[data-dragging] {
  cursor: grabbing;
}

.wc-map-canvas[hidden],
.wc-map-notice[hidden] {
  display: none;
}

.wc-map-notice {
  position: absolute;
  inset: 0;
  white-space: pre-wrap;
  color: var(--term-fg);
  pointer-events: none;
}

/* Map loading overlay (src/panes/map-loading.ts, stage 24 round 1): a
 * small, modern indicator centred over the map, a contrast to the TUI
 * look of the rest of the client (the mapper is the modern window). A
 * system UI label over a thin rounded bar on a soft translucent pill.
 * Colours are fixed neutral tones, not terminal tokens: the map's
 * background (`.wc-map`, #2e3436 unless set in Options → Mapper, ADR 0085)
 * does not follow the theme, so the overlay does not either; its dark pill
 * reads on every background in the Mapper list.
 * Fades out at the end. */
.wc-map-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  opacity: 1;
  transition: opacity 250ms ease-out;
}

.wc-map-loading[hidden] {
  display: none;
}

.wc-map-loading[data-leaving] {
  opacity: 0;
}

.wc-map-loading-box {
  box-sizing: content-box;
  width: min(180px, 60%);
  padding: 8px 12px 10px;
  border-radius: 10px;
  background: rgba(36, 40, 42, 0.9);
  box-shadow: 0 1px 6px rgba(0, 0, 0, 0.18);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  color: rgba(238, 238, 236, 0.72);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
  letter-spacing: 0.01em;
}

.wc-map-loading-label {
  overflow: hidden;
  white-space: pre;
  text-overflow: ellipsis;
  text-align: center;
  margin-bottom: 6px;
}

.wc-map-loading-bar {
  height: 3px;
  border-radius: 999px;
  background: rgba(238, 238, 236, 0.16);
  overflow: hidden;
}

/* A full-width strip slid in from the left (map-loading.ts): the
 * transition runs on the compositor and the leading end stays round. */
.wc-map-loading-fill {
  height: 100%;
  border-radius: inherit;
  background: rgba(238, 238, 236, 0.85);
  transform: translateX(-100%);
  transition: transform 220ms ease-out;
}

.wc-map-loading[data-reset] .wc-map-loading-fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .wc-map-loading,
  .wc-map-loading-fill {
    transition: none;
  }
}

/* Map hover box (src/panes/map-hover.ts, ADR 0077 and its round 1): the
 * room under a resting pointer, in the tooltip look of the script panes.
 * Fixed in the cockpit, near the pointer, so it may extend past the Map
 * pane's edges; the script keeps it inside the viewport. Width capped in
 * `ch` of its own text size, long lines wrap. Text size: Options → Mapper "Hover text size"
 * (Small / Medium / Large = 0.72 / 0.85 / 1 of the cockpit font, round 2). */
.wc-map-hover {
  position: fixed;
  z-index: 250;
  box-sizing: border-box;
  max-width: min(36ch, calc(100vw - 8px));
  max-height: calc(100vh - 8px);
  overflow: hidden;
  padding: 0 1ch;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-family: var(--font-mono);
  /* Medium (the default): 0.85 of the cockpit font (round 2). */
  font-size: calc(var(--font-size) * 0.85);
  line-height: calc(var(--cell-h) * 0.85);
  letter-spacing: normal;
  color: var(--c-body, var(--term-fg));
  background: var(--c-line-hl, #303030);
  pointer-events: none;
}

.wc-map-hover[data-size="small"] {
  font-size: calc(var(--font-size) * 0.72);
  line-height: calc(var(--cell-h) * 0.72);
}

.wc-map-hover[data-size="large"] {
  font-size: var(--font-size);
  line-height: var(--cell-h);
}

.wc-map-hover.is-full {
  max-width: min(56ch, calc(100vw - 8px));
}

.wc-map-hover[hidden] {
  display: none;
}

/* The room name in green, as the game shows it (Cockpit: ANSI green);
 * `--c-ok` is the theme's green, kept readable on dark and light
 * backgrounds (ADR 0041). */
.wc-map-hover-name {
  color: var(--c-ok, var(--term-fg));
  font-weight: bold;
}

/* Contents: italic, as MMapper's room preview. */
.wc-map-hover-contents {
  font-style: italic;
}

.wc-map-hover-exits {
  color: var(--c-item, var(--term-fg));
}

.wc-map-hover-note {
  color: var(--c-hint, var(--term-fg));
  font-style: italic;
}

.wc-map-hover-label {
  color: var(--c-body, var(--term-fg));
  font-style: normal;
  font-weight: bold;
}

.wc-map-hover-more {
  color: var(--c-hint, var(--term-fg));
}

/* Script panes (src/panes/script-pane.ts, ADR 0053): a link's hint, one
 * cell row per line, under the link and over everything in the cockpit
 * (as the log player's marker tips, ADR 0032). */
.wc-spane-tip {
  position: absolute;
  z-index: 200;
  white-space: pre;
  line-height: var(--cell-h);
  color: var(--c-body, var(--term-fg));
  background: var(--c-line-hl, #303030);
  pointer-events: none;
}

.wc-spane-tip[hidden] {
  display: none;
}

.wc-spane-tip > div {
  height: var(--cell-h);
}

/* Script pane text fields (ADR 0055): a native input over whole cells, in
 * the cockpit font and cell advance, without a browser look. The band
 * under it is drawn in the cells (the pane's track shade), so it follows
 * the tint; the text and placeholder colours come from the pane. */
.wc-spane-fields {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  overflow: visible;
}

.wc-spane-field {
  position: absolute;
  box-sizing: border-box;
  height: var(--cell-h);
  margin: 0;
  padding: 0;
  border: 0;
  outline: none;
  border-radius: 0;
  background: transparent;
  font: inherit;
  letter-spacing: inherit;
  line-height: var(--cell-h);
  caret-color: currentColor;
}

.wc-spane-field::placeholder {
  color: var(--spane-ph, currentColor);
  opacity: 1;
}

.wc-spane-field::selection {
  color: var(--spane-sel-fg, inherit);
  background: var(--spane-sel-bg, highlight);
}

/* Script pane scrolling (ADR 0053 addendum, as ADR 0052): every line in a
 * native scroller with the bar hidden; one indicator row above (a console)
 * or below (a list) it when the lines overflow. */
.wc-spane-scroll {
  position: absolute;
  left: 0;
  width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  overflow-anchor: none;
  scrollbar-width: none;
}

.wc-spane-scroll::-webkit-scrollbar {
  display: none;
}

.wc-spane-rows {
  position: relative;
}

.wc-spane-more {
  position: absolute;
  left: 0;
  width: 100%;
}

.wc-spane-more[hidden] {
  display: none;
}

.wc-spane-more[data-away] {
  cursor: pointer;
}

/* Comm pane (src/panes/comm.ts, ADR 0134): the chat column, the spine, the
 * thread with its top bar (search; folded: unfold and the open chat's
 * chip) and the reply line. In the pane's font, sizes in em of it.
 *
 * Colours come from the pane tint as in Group and Timers (ADR 0122, 0123):
 * `--cm-fg` / `--cm-dim` are the pane's shade ramp (set by the pane),
 * `--lamp`, `--frost2`, `--frost-edge`, `--card-back` the lantern's
 * (layout.css); a person's or a channel's colour comes per element as
 * `--pc` / `--cc` (fitted for a light pane by the script). Surfaces are
 * flat colours (no gradients: cheap to paint with many rows, as the Timers
 * chips). Nothing animates per message: the column's width, the spine and
 * the search field ease only on a user's action.
 *
 * Your own lines ("Stilla ton", owner 2026-11-09): a flat, faint lamp tone,
 * no gradient, no edge bar, no indent; your bubbles right in the same tone. */

.wc-comm {
  position: absolute;
  inset: 0;
  contain: strict;
  display: flex;
  white-space: normal;
  line-height: 1.3;
  color: var(--cm-fg);
  --cm-self: color-mix(in oklab, var(--lamp) 62%, #fff1cf);
  --cm-hot: color-mix(in srgb, var(--cm-fg) 55%, #fff);
  --cm-card: color-mix(in srgb, var(--lamp) 8%, var(--card-back, transparent));
  --cm-lit: inset 0 1px 0 color-mix(in srgb, var(--lamp) 22%, transparent);
  --cm-drop: 0 1px 2px rgb(0 0 0 / 0.45);
  --cm-bub-base: var(--card-back, transparent);
  --cm-bub: 18%;
  --cm-mine: 7%;
  --cm-mine-bub: 10%;
  --cm-mine-edge: 12%;
  --cm-sel: color-mix(in srgb, var(--lamp) 15%, transparent);
  --cm-badge-bg: #f0b84f;
  --cm-badge-ink: #170f03;
  /* What floats over the thread (the search, unfold, the chip): opaque, so
   * text scrolling under it does not show through. */
  --cm-float: color-mix(in srgb, var(--lamp) 10%, var(--pane-fill, var(--pane-bg, #000)));
}

/* Paper (ADR 0123 "Paper"): raised paper cards, the pane's dark ink. */
.wc-comm[data-light] {
  --cm-self: oklch(from var(--pane-border) 0.45 min(calc(c * 1.6), 0.09) h);
  --cm-hot: var(--ink, var(--cm-fg));
  --cm-card: color-mix(in srgb, #fffdf8 92%, var(--card-back, transparent));
  --cm-lit: 0 0 transparent;
  --cm-drop: 0 1px 2px rgb(60 40 10 / 0.22);
  --cm-bub-base: color-mix(in srgb, #fffdf8 90%, var(--card-back, transparent));
  --cm-bub: 14%;
  --cm-mine: 9%;
  --cm-mine-bub: 9%;
  --cm-mine-edge: 22%;
  --cm-sel: color-mix(in srgb, var(--cm-self) 14%, transparent);
  --cm-badge-bg: #8a5a0e;
  --cm-badge-ink: #fffaf0;
  --cm-float: #fffdf8;
}

.wc-comm [hidden] {
  display: none !important;
}

.wc-comm button {
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-align: inherit;
  cursor: pointer;
}

.wc-comm button:focus-visible {
  outline: 1px solid color-mix(in srgb, var(--cm-self) 70%, transparent);
  outline-offset: 1px;
}

.wc-cm-i {
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ------------------------------------------------------------- column */

.wc-cm-col {
  flex: none;
  display: flex;
  flex-direction: column;
  width: var(--cm-colw, 9em);
  min-height: 0;
  padding: 0.2em 0 0.2em 0.15em;
  box-sizing: border-box;
  user-select: none;
  transition: width 0.18s ease-out;
  /* A change in the column (a snippet, a badge, a raised chat) lays out
   * and paints the column only, never the thread beside it. */
  contain: strict;
}

.wc-comm[data-mode='folded'] > .wc-cm-col,
.wc-comm[data-mode='folded'] > .wc-cm-spine {
  display: none;
}

.wc-comm[data-dragging] > .wc-cm-col {
  transition: none;
}

.wc-cm-pins {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* Between Group and the private chats. */
.wc-cm-gap {
  flex: none;
  height: 1px;
  margin: 0.45em 0.5em;
  background: var(--frost-edge);
  opacity: 0.6;
}

.wc-cm-chatwrap {
  position: relative;
  flex: 1 1 0;
  min-height: 0;
}

/* The private chats fill from the top, newest last; the bar is hidden.
 * The scroller runs bottom-up (column-reverse: its scroll origin is the
 * bottom), so an overflowing list starts at the newest chat and keeps to it
 * without a script reading or writing the scroll position; its one child,
 * the list, is pushed to the top while it is short by an auto margin (not
 * justify-content, which would put an overflow out of reach). */
.wc-cm-chats {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column-reverse;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.wc-cm-chats::-webkit-scrollbar {
  display: none;
}

.wc-cm-chatlist {
  flex: none;
  margin-bottom: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  /* The newest chat clear of the pane's bottom edge (a dock handle's grip
   * lies over the last pixels). */
  padding-bottom: 0.45em;
}

/* More above or below: the edge fades out (a mask on the box, so it does
 * not move with the rows) and a small chevron sits in the fade. */
.wc-cm-chatwrap[data-up] > .wc-cm-chats {
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 2.2em);
  mask-image: linear-gradient(to bottom, transparent 0, #000 2.2em);
}

.wc-cm-chatwrap[data-down] > .wc-cm-chats {
  -webkit-mask-image: linear-gradient(to top, transparent 0, #000 2.2em);
  mask-image: linear-gradient(to top, transparent 0, #000 2.2em);
}

.wc-cm-chatwrap[data-up][data-down] > .wc-cm-chats {
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 2.2em, #000 calc(100% - 2.2em), transparent 100%);
  mask-image: linear-gradient(to bottom, transparent 0, #000 2.2em, #000 calc(100% - 2.2em), transparent 100%);
}

.wc-comm .wc-cm-chev {
  position: absolute;
  left: 50%;
  z-index: 1;
  display: none;
  width: 1.5em;
  height: 1em;
  transform: translateX(-50%);
  color: color-mix(in srgb, var(--cm-self) 60%, transparent);
  /* A hint only: the row under it keeps its clicks (the wheel scrolls). */
  pointer-events: none;
}

.wc-cm-chev .wc-cm-i {
  width: 100%;
  height: 100%;
}

.wc-cm-chev.is-up {
  top: 0;
}

.wc-cm-chev.is-down {
  bottom: 0;
}

.wc-cm-chatwrap[data-up] > .wc-cm-chev.is-up,
.wc-cm-chatwrap[data-down] > .wc-cm-chev.is-down {
  display: block;
}

.wc-comm .wc-cm-chev:hover {
  color: var(--cm-self);
}

/* A hidden chat has unread: a small dot on the chevron, no number. */
.wc-cm-chev[data-unread]::after,
.wc-cm-unfold[data-unread]::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 0.4em;
  height: 0.4em;
  border-radius: 50%;
  background: var(--cm-badge-bg);
}

/* A chat, Public or Group. */
.wc-comm .wc-cm-ent {
  position: relative;
  display: grid;
  grid-template-columns: 1.9em minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.45em;
  flex: none;
  padding: 0.2em 0.35em 0.2em 0.25em;
  border-radius: 0.35em;
  color: var(--cm-fg);
}

.wc-comm .wc-cm-ent:hover {
  background: var(--frost2);
}

.wc-comm .wc-cm-ent[aria-pressed='true'] {
  background: var(--cm-sel);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 30%, transparent);
}

.wc-cm-ent[data-dim] {
  opacity: 0.45;
}

.wc-cm-av {
  display: grid;
  place-items: center;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  box-sizing: border-box;
  font-weight: bold;
  line-height: 1;
  color: var(--pc);
  background: color-mix(in srgb, var(--pc) 16%, var(--cm-bub-base));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 45%, transparent);
}

.wc-cm-av .wc-cm-i {
  width: 1.15em;
  height: 1.15em;
}

.wc-cm-et {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  line-height: 1.2;
}

.wc-cm-r2 {
  min-width: 0;
}

.wc-cm-r1 {
  display: flex;
  align-items: baseline;
  gap: 0.4em;
  min-width: 0;
}

.wc-cm-r1 > b {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--pc);
}

.wc-cm-ago {
  flex: none;
  font-size: 0.78em;
  color: var(--cm-dim);
  font-variant-numeric: tabular-nums;
}

.wc-cm-sn {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.82em;
  color: var(--cm-dim);
}

.wc-cm-badge {
  min-width: 1.35em;
  height: 1.35em;
  padding: 0 0.3em;
  box-sizing: border-box;
  border-radius: 0.7em;
  font-size: 0.72em;
  font-weight: bold;
  line-height: 1.35em;
  text-align: center;
  color: var(--cm-badge-ink);
  background: var(--cm-badge-bg);
}

.wc-cm-badge[data-dot] {
  min-width: 0;
  width: 0.55em;
  height: 0.55em;
  padding: 0;
  border-radius: 50%;
}

/* A short pane (`data-compact`, under 14 cell rows): one line per entry,
 * a smaller disc, no snippet, so the private chats keep room. */
.wc-comm[data-compact] .wc-cm-ent {
  grid-template-columns: 1.45em minmax(0, 1fr) auto;
  padding-top: 0.1em;
  padding-bottom: 0.1em;
}

.wc-comm[data-compact] .wc-cm-av {
  width: 1.45em;
  height: 1.45em;
}

.wc-comm[data-compact] .wc-cm-av .wc-cm-i {
  width: 0.95em;
  height: 0.95em;
}

.wc-comm[data-compact] .wc-cm-r2 {
  display: none;
}

.wc-comm[data-compact] .wc-cm-gap {
  margin: 0.25em 0.5em;
}

/* The rail: discs only (the name in the tooltip), the badge on the disc. */
.wc-comm[data-mode='rail'] .wc-cm-ent {
  grid-template-columns: 1fr;
  justify-items: center;
  padding: 0.2em 0;
}

.wc-comm[data-mode='rail'] .wc-cm-et {
  display: none;
}

.wc-comm[data-mode='rail'] .wc-cm-badge {
  position: absolute;
  top: 0;
  right: 0.1em;
}

/* --------------------------------------------------------------- spine */

/* Between the column and the thread: invisible at rest; on hover, while
 * dragged or focused its line (with a gap round the handle) and the
 * handle fade in. A wider hit zone than it looks. */
.wc-cm-spine {
  position: relative;
  flex: none;
  width: 7px;
  cursor: col-resize;
  touch-action: none;
}

.wc-cm-spine::after {
  content: '';
  position: absolute;
  inset: 0 -3px;
}

.wc-cm-spine::before {
  content: '';
  position: absolute;
  top: 6%;
  bottom: 6%;
  left: 3px;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent 0,
    var(--cm-spine, var(--frost-edge)) 12%,
    var(--cm-spine, var(--frost-edge)) calc(50% - 1.2em),
    transparent calc(50% - 1.2em),
    transparent calc(50% + 1.2em),
    var(--cm-spine, var(--frost-edge)) calc(50% + 1.2em),
    var(--cm-spine, var(--frost-edge)) 88%,
    transparent 100%
  );
  opacity: 0;
  transition: opacity 0.18s;
}

.wc-comm .wc-cm-handle {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 1.15em;
  height: 1.6em;
  transform: translate(-50%, -50%);
  border-radius: 0.4em;
  color: color-mix(in srgb, var(--cm-self) 75%, var(--cm-dim));
  background: var(--cm-float);
  box-shadow: inset 0 0 0 1px var(--frost-edge), var(--cm-drop);
  opacity: 0;
  transition: opacity 0.18s;
  cursor: pointer;
}

/* The chevron points the way the column folds. */
.wc-cm-handle > .wc-cm-i {
  width: 0.95em;
  height: 0.95em;
  stroke-width: 2.4;
}

.wc-comm .wc-cm-handle:hover {
  color: var(--cm-self);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cm-self) 45%, transparent), var(--cm-drop);
}

.wc-cm-spine:hover,
.wc-comm[data-dragging] > .wc-cm-spine {
  --cm-spine: color-mix(in srgb, var(--cm-self) 55%, transparent);
}

.wc-cm-spine:hover::before,
.wc-cm-spine:focus-within::before,
.wc-comm[data-dragging] > .wc-cm-spine::before,
.wc-cm-spine:hover > .wc-cm-handle,
.wc-cm-spine:focus-within > .wc-cm-handle,
.wc-comm[data-dragging] > .wc-cm-spine > .wc-cm-handle {
  opacity: 1;
}

@media (hover: none) {
  .wc-cm-spine::before,
  .wc-comm .wc-cm-handle {
    opacity: 0.6;
  }
}

/* -------------------------------------------------------------- thread */

.wc-cm-main {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: 0 0.25em 0.25em 0.15em;
  contain: layout paint style;
}

/* Over the thread's top: folded, unfold and the open chat's chip at the
 * left; the search at the right. The thread starts below it. */
.wc-cm-top {
  position: absolute;
  top: 0.2em;
  left: 0.15em;
  right: 0.25em;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 0.35em;
  height: 1.7em;
  pointer-events: none;
}

.wc-cm-top > * {
  pointer-events: auto;
}

.wc-comm .wc-cm-unfold,
.wc-comm .wc-cm-sbtn {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.7em;
  border-radius: 50%;
  color: color-mix(in srgb, var(--cm-fg) 80%, transparent);
}

.wc-comm .wc-cm-unfold {
  background: var(--cm-float);
  box-shadow: var(--cm-lit), inset 0 0 0 1px var(--frost2), var(--cm-drop);
}

.wc-cm-unfold .wc-cm-i,
.wc-cm-sbtn .wc-cm-i {
  width: 1em;
  height: 1em;
}

.wc-comm .wc-cm-unfold:hover,
.wc-comm .wc-cm-sbtn:hover {
  color: var(--cm-hot);
}

.wc-comm .wc-cm-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
  min-width: 0;
  max-width: 60%;
  height: 1.7em;
  padding: 0 0.65em 0 0.15em;
  box-sizing: border-box;
  border-radius: 0.85em;
  color: var(--pc);
  background: var(--cm-float);
  box-shadow: var(--cm-lit), inset 0 0 0 1px color-mix(in srgb, var(--pc) 30%, transparent), var(--cm-drop);
}

.wc-cm-chip > .wc-cm-av {
  flex: none;
  width: 1.4em;
  height: 1.4em;
  font-size: 0.9em;
}

.wc-cm-chip > b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wc-comm[data-search] .wc-cm-chip {
  display: none;
}

/* The search: a round button that grows into a field. */
.wc-cm-search {
  display: flex;
  align-items: center;
  flex: none;
  width: 1.7em;
  height: 1.7em;
  margin-left: auto;
  overflow: hidden;
  border-radius: 0.85em;
  background: var(--cm-float);
  box-shadow: var(--cm-lit), inset 0 0 0 1px var(--frost2), var(--cm-drop);
  transition: width 0.18s ease-out;
}

.wc-comm[data-search] .wc-cm-search {
  flex: 1 1 auto;
  width: 100%;
}

/* Read-only (the phone's layout over a replay, stage 55): no search, so no well for its key either. */
.wc-comm[data-readonly] .wc-cm-search {
  display: none;
}

.wc-cm-sinput,
.wc-cm-rinput {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  font: inherit;
  letter-spacing: inherit;
  color: var(--cm-hot);
  caret-color: var(--cm-self);
}

.wc-cm-sinput::-webkit-search-cancel-button {
  display: none;
}

.wc-cm-sinput::placeholder,
.wc-cm-rinput::placeholder {
  color: var(--cm-dim);
  opacity: 1;
}

/* The reply line's "Reply to …" / "Tell the group…": a step quieter than
 * the dim text, still about 3:1 on its card (owner's first test). */
.wc-cm-rinput::placeholder {
  color: color-mix(in srgb, var(--cm-dim) 72%, var(--cm-float));
}

/* A phone's reply line is a one-row <textarea> (no autofill bar; src/panes/comm.ts): it behaves as
 * the <input> it stands in for. Only a phone has the textarea; the desktop's is an <input>. */
textarea.wc-cm-rinput {
  display: block;
  height: 1.4em;
  line-height: 1.4;
  resize: none;
  overflow: hidden;
  white-space: pre;
  overflow-wrap: normal;
  scrollbar-width: none;
}

.wc-comm:not([data-search]) .wc-cm-sinput,
.wc-comm:not([data-search]) .wc-cm-sclear {
  visibility: hidden;
}

.wc-comm .wc-cm-sclear {
  flex: none;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.7em;
  color: var(--cm-dim);
}

.wc-cm-sclear .wc-cm-i {
  width: 0.75em;
  height: 0.75em;
}

/* Unfolded, only the round search button floats over the thread's top;
 * folded or searching, the top bar has a row of its own. */
.wc-comm .wc-cm-thread {
  padding: 2.1em 0.1em 0.3em;
}

/* Borderless, the pane's hover buttons lie over the content's top row
 * (ADR 0095): the top bar goes under them. */
.wc-pane:not([data-framed]) .wc-cm-top {
  top: calc(var(--cell-h, 17px) + 0.1em);
}

.wc-pane:not([data-framed]) .wc-comm .wc-cm-thread,
.wc-pane:not([data-framed]) .wc-comm .wc-cm-results {
  padding-top: calc(var(--cell-h, 17px) + 2.1em);
}

.wc-pane:not([data-framed]) .wc-comm[data-mode='folded'] .wc-cm-thread,
.wc-pane:not([data-framed]) .wc-comm[data-mode='folded'] .wc-cm-results,
.wc-pane:not([data-framed]) .wc-comm[data-search] .wc-cm-results {
  margin-top: calc(var(--cell-h, 17px) + 2.1em);
  padding-top: 0.1em;
}

.wc-comm[data-mode='folded'] .wc-cm-thread,
.wc-comm[data-mode='folded'] .wc-cm-results,
.wc-comm[data-search] .wc-cm-results {
  margin-top: 2.1em;
  padding-top: 0.1em;
}

/* Block flow, not flex: a new message lays out only itself (a flex column
 * of hundreds of rows lays them all out again on every append). Bubbles
 * and the centred lines are fit-content boxes placed by their margins. */
.wc-cm-thread > .wc-alist-stack > div {
  white-space: normal;
}

.wc-cm-item {
  display: flow-root;
}

/* The time between two messages far apart. */
.wc-cm-sep {
  width: fit-content;
  margin: 0.7em auto 0.15em;
  padding: 0 0.5em;
  border-radius: 0.5em;
  font-size: 0.75em;
  color: var(--cm-dim);
  background: var(--card-back, transparent);
  font-variant-numeric: tabular-nums;
  user-select: none;
}

/* Public and Group: one line per message. */
.wc-cm-ln {
  padding: 0.05em 0.35em;
  border-radius: 0.2em;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  background: var(--card-back, transparent);
}

.wc-cm-item + .wc-cm-item > .wc-cm-ln:first-child {
  margin-top: 1px;
}

.wc-cm-ln[data-mine] {
  background: color-mix(in srgb, var(--cm-self) var(--cm-mine), var(--card-back, transparent));
}

.wc-cm-tx {
  color: var(--cm-fg);
}

/* A chat's talk between you and that person (and group tells). */
.wc-cm-bb {
  position: relative;
  width: fit-content;
  max-width: 80%;
  margin-top: 0.4em;
  padding: 0.15em 0.6em;
  box-sizing: border-box;
  border-radius: 0.75em 0.75em 0.75em 0.2em;
  background: color-mix(in srgb, var(--pc) var(--cm-bub), var(--cm-bub-base));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 18%, transparent);
}

.wc-comm[data-light] .wc-cm-bb {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 30%, transparent), var(--cm-drop);
}

.wc-cm-bb.is-cont {
  margin-top: 0.12em;
}

.wc-cm-bb.is-me {
  margin-left: auto;
  border-radius: 0.75em 0.75em 0.2em 0.75em;
  background: color-mix(in srgb, var(--cm-self) var(--cm-mine-bub), var(--cm-bub-base));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cm-self) var(--cm-mine-edge), transparent);
}

.wc-comm[data-light] .wc-cm-bb.is-me {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cm-self) var(--cm-mine-edge), transparent), var(--cm-drop);
}

.wc-cm-bb.is-wh {
  outline: 1px dashed color-mix(in srgb, var(--pc) 55%, transparent);
  outline-offset: -1px;
}

.wc-cm-bt {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--cm-hot);
}

.wc-cm-bb.is-me > .wc-cm-bt {
  color: var(--cm-fg);
}

/* Under a group tell's bubble in a person's chat: always shown, small and
 * very quiet, on a little line of its own (it was said to the whole group,
 * maybe not meant for you). */
.wc-cm-gt {
  margin: 0.05em 0 0 0.7em;
  font-size: 0.66em;
  line-height: 1.2;
  letter-spacing: 0.03em;
  color: color-mix(in srgb, var(--cm-dim) 65%, transparent);
  user-select: none;
}

.wc-comm[data-light] .wc-cm-gt {
  color: color-mix(in srgb, var(--cm-dim) 75%, transparent);
}

.wc-cm-gt.is-me {
  margin: 0.05em 0.7em 0 0;
  text-align: right;
}

/* The channel and time: beside the bubble (outside it, in the thread's
 * free side), shown only while that bubble is hovered; it takes no height,
 * so a bubble is one text line tall. Small and quiet, the word over the
 * time. Kept in the DOM (readers, copy excluded). Touch: never shown. */
.wc-cm-bm {
  position: absolute;
  bottom: 0.1em;
  left: 100%;
  display: flex;
  flex-direction: column;
  margin-left: 0.45em;
  font-size: 0.62em;
  line-height: 1.15;
  white-space: nowrap;
  color: color-mix(in srgb, var(--cm-dim) 75%, transparent);
  font-variant-numeric: tabular-nums;
  user-select: none;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s;
}

.wc-cm-bb.is-me > .wc-cm-bm {
  left: auto;
  right: 100%;
  align-items: flex-end;
  margin: 0 0.45em 0 0;
}

.wc-cm-bmsep {
  display: none;
}

@media (hover: hover) {
  .wc-cm-bb:hover > .wc-cm-bm {
    opacity: 1;
  }
}

/* Everything else in a chat (say, emote, social, an undirected whisper or
 * question, narrate, yell, song, prayer): a line as in Public, left-aligned
 * and whole, with no bubble (maybe not to you): a little smaller and
 * quieter, on the card backing only; your own with Public's faint tint. */
.wc-cm-oh {
  margin: 0.4em 0 0.05em;
  padding: 0.05em 0.35em;
  border-radius: 0.2em;
  font-size: 0.9em;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--cm-dim);
  background: var(--card-back, transparent);
}

.wc-cm-oh[data-mine] {
  background: color-mix(in srgb, var(--cm-self) var(--cm-mine), var(--card-back, transparent));
}

.wc-cm-oh .wc-cm-tx {
  color: color-mix(in srgb, var(--cm-fg) 72%, var(--cm-dim));
}

/* Group: joined / left. */
.wc-cm-note {
  width: fit-content;
  margin: 0.5em auto 0.1em;
  padding: 0 0.6em;
  border-radius: 0.6em;
  font-size: 0.8em;
  color: var(--cm-dim);
  background: var(--card-back, transparent);
  box-shadow: inset 0 0 0 1px var(--frost-edge);
  user-select: none;
}

.wc-comm .wc-cm-more {
  align-self: center;
  height: auto;
  margin-top: 0.2em;
  padding: 0 0.7em;
  border-radius: 0.7em;
  font-size: 0.8em;
  font-style: normal;
  line-height: 1.6;
  color: var(--cm-badge-ink);
  background: var(--cm-badge-bg);
}

/* ------------------------------------------------------------- results */

.wc-cm-results {
  flex: 1 1 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 0.25em;
  padding: 2.1em 0.1em 0.3em;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.wc-cm-results::-webkit-scrollbar {
  display: none;
}

.wc-cm-rh {
  display: flex;
  align-items: center;
  gap: 0.5em;
  margin-top: 0.4em;
  font-size: 0.72em;
  font-weight: bold;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cm-dim);
  user-select: none;
}

.wc-cm-rh::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--frost-edge);
}

.wc-comm .wc-cm-rp {
  display: grid;
  grid-template-columns: 1.9em minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.5em;
  flex: none;
  padding: 0.25em 0.5em 0.25em 0.3em;
  border-radius: 0.4em;
  background: color-mix(in srgb, var(--pc) 12%, var(--cm-bub-base));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 24%, transparent), var(--cm-drop);
}

.wc-comm .wc-cm-rp:hover {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pc) 60%, transparent), var(--cm-drop);
}

.wc-cm-rpt {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  line-height: 1.2;
}

.wc-cm-rpt > b {
  color: var(--pc);
}

.wc-cm-rpt > small {
  font-size: 0.8em;
  color: var(--cm-dim);
}

.wc-cm-go {
  font-size: 0.8em;
  white-space: nowrap;
  color: var(--cm-hot);
}

.wc-cm-rm {
  flex: none;
  padding: 0.15em 0.35em 0.2em 0.45em;
  border-left: 2px solid color-mix(in srgb, var(--cc) 70%, transparent);
  border-radius: 0 0.3em 0.3em 0;
  background: var(--card-back, transparent);
}

.wc-cm-rmh {
  font-size: 0.72em;
  color: var(--cm-dim);
  user-select: none;
}

.wc-cm-rmt {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.wc-comm mark {
  border-radius: 2px;
  color: inherit;
  background: color-mix(in srgb, var(--cm-badge-bg) 38%, transparent);
}

.wc-cm-none {
  font-size: 0.85em;
  color: var(--cm-dim);
}

/* --------------------------------------------------------------- reply */

.wc-cm-reply {
  flex: none;
  display: flex;
  align-items: center;
  margin-top: 0.3em;
  padding: 0.15em 0.5em;
  border-left: 2px solid color-mix(in srgb, var(--pc, var(--cm-self)) 70%, transparent);
  border-radius: 0.35em;
  background: var(--cm-card);
  box-shadow: var(--cm-lit), inset 0 0 0 1px var(--frost2), var(--cm-drop);
}

@media (prefers-reduced-motion: reduce) {
  .wc-cm-col,
  .wc-cm-search,
  .wc-cm-spine::before,
  .wc-comm .wc-cm-handle,
  .wc-cm-bm {
    transition: none;
  }
}

/* The countdown ring of the Group and Timers panes (src/panes/icons.ts
 * `ringSvg`, ADR 0122): a track and an arc that drains clockwise from the
 * top. A pane tunes it with custom properties on the ring or above it:
 *   --ring-track    the track's colour
 *   --ring-color    the arc's colour (default currentColor)
 *   --ring-w        the stroke width in view-box units (default 2.2)
 *   --ring-unknown  an unknown (dashed) arc's colour (default the arc's)
 *   --ring-unknown-opacity */

.wc-ring-bg,
.wc-ring-arc {
  fill: none;
  stroke-width: var(--ring-w, 2.2);
}

.wc-ring-bg {
  stroke: var(--ring-track, currentColor);
}

.wc-ring-arc {
  stroke: var(--ring-color, currentColor);
  stroke-linecap: round;
  transform: rotate(-90deg);
  transform-origin: 12px 12px;
}

.wc-ring-arc.is-unknown {
  stroke: var(--ring-unknown, var(--ring-color, currentColor));
  opacity: var(--ring-unknown-opacity, 1);
  stroke-dasharray: 2.4 3.2 !important;
}

/* Pane tooltips (src/panes/pane-tooltip.ts, ADR 0122): a small card in the
 * menu surface colours (ADR 0116), a bold first line and the text. Fixed,
 * above the panes and the menu bar's popups' layer below it. */

.wc-ptip {
  position: fixed;
  z-index: 275;
  box-sizing: border-box;
  max-width: 260px;
  padding: 5px 9px 6px;
  border: 1px solid var(--sf-border, #2c2c2c);
  border-radius: 5px;
  background: var(--sf-bg, #0a0a0a);
  box-shadow: var(--sf-shadow, 0 10px 26px rgba(0, 0, 0, 0.75));
  color: var(--sf-fg, #c4c4c4);
  font-family: var(--font-mono);
  font-size: calc(var(--font-size, 15px) * 0.78);
  font-weight: normal;
  line-height: 1.35;
  letter-spacing: normal;
  white-space: pre-line;
  text-align: left;
  pointer-events: none;
}

.wc-ptip[hidden] {
  display: none;
}

.wc-ptip > b {
  display: block;
  margin-bottom: 1px;
  color: var(--sf-hot, #ebebeb);
  font-weight: bold;
}

.wc-ptip > b[hidden] {
  display: none;
}

/* The Group pane (src/panes/group.ts, ADR 0122, mockup 3c). DOM rows on the
 * cell grid: a one-line row is one cell high, a two-line member and each
 * line of the fight zone too. Colours: the pane's shade ramp (`--gp-*`,
 * set per render from paneShade) for text and lines; the icons and bars
 * carry their own colour inline.
 *
 * The lantern look (ADR 0123, stage 40b): the fight card and every member
 * row are frosted glass catching the pane's lamp (`--lamp`, layout.css),
 * on `--card-back` (a clear pane's backing); the bars are glossy tubes in a
 * dark recessed track. All of it is static paint on elements that do not
 * change on a tick: a value moves only a fill (a transform) or sets a text.
 * A member card is the row's `::before`, inset from the row's cell box, so
 * the cards have air between them and the rows keep their cell grid.
 * On a light pane (Paper) the cards are raised paper instead (the end of
 * this file). */

.wc-gp {
  /* The pane content has a fixed size and clips (layout.css): a change in
   * here never lays out or repaints anything outside it. */
  contain: strict;
  --gp-row: var(--cell-h, 17px);
  --gp-hover: color-mix(in srgb, var(--gp-text, #ccc) 7%, transparent);
  /* Frosted glass: the lamp's frost on the card backing, a lit top edge, a
   * faint rim and a small shadow under it. One flat colour (the mockup's
   * frost gradient cost Firefox about 0.3 ms a Group update). */
  --gp-card: color-mix(in srgb, var(--lamp) 8%, var(--card-back, transparent));
  --gp-card-hover: color-mix(in srgb, var(--lamp) 13%, var(--card-back, transparent));
  --gp-card-edge:
    inset 0 1px 0 color-mix(in srgb, var(--lamp) 26%, transparent),
    inset 0 0 0 1px var(--frost2),
    0 1px 2px rgb(0 0 0 / 0.45);
  /* The tube's track: dark and recessed, a lamp-lit lip under it. */
  --gp-trk: rgb(0 0 0 / 0.55);
  --gp-trk-edge: inset 0 1px 1px rgb(0 0 0 / 0.7), 0 1px 0 color-mix(in srgb, var(--lamp) 14%, transparent);
  /* The fill's gloss over its own colour: a highlight on top, a shade below. */
  --gp-gloss: linear-gradient(180deg, rgb(255 255 255 / 0.38), rgb(255 255 255 / 0) 55%, rgb(0 0 0 / 0.15));
  display: flex;
  flex-direction: column;
  white-space: nowrap;
  color: var(--gp-text, #c4c4c4);
  line-height: var(--gp-row);
}

.wc-gp svg {
  display: block;
}

.wc-gp-i {
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.wc-gp-row {
  box-sizing: border-box;
  flex: none;
  min-width: 0;
  padding: 0 calc(var(--cell-w, 9px) * 0.4);
  border-radius: 3px;
}

/* ------------------------------------------------------------ members */

.wc-gp-m2 {
  display: flex;
  flex-direction: column;
  height: calc(var(--gp-row) * 2);
}

/* The member's card: behind the row's content (the row is its own
 * stacking context), a pixel in from the top and two from the bottom of
 * the row's cells. */
.wc-gp-m2,
.wc-gp-m1 {
  position: relative;
  isolation: isolate;
}

.wc-gp-m2::before,
.wc-gp-m1::before {
  content: '';
  position: absolute;
  inset: 1px 0 2px;
  z-index: -1;
  border-radius: 4px;
  background: var(--gp-card);
  box-shadow: var(--gp-card-edge);
  pointer-events: none;
}

/* A one-line row's card is a cell high: a pixel of air each side. */
.wc-gp-m1::before {
  inset: 1px 0;
  border-radius: 3px;
}

/* The name line sits a pixel lower, clear of the card's lit top edge (no
 * layout: a relative offset). */
.wc-gp-m2 > .wc-gp-l1 {
  position: relative;
  top: 1px;
}

.wc-gp-m2:hover::before,
.wc-gp-m1:hover::before {
  background: var(--gp-card-hover);
}

.wc-gp-l1 {
  display: flex;
  align-items: center;
  gap: calc(var(--cell-w, 9px) * 0.7);
  height: var(--gp-row);
  min-width: 0;
}

.wc-gp-mk {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: calc(var(--gp-row) * 0.95);
  height: var(--gp-row);
}

.wc-gp-mk svg {
  width: calc(var(--gp-row) * 0.8);
  height: calc(var(--gp-row) * 0.8);
}

.wc-gp-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--gp-label);
}

.wc-gp-name.is-player {
  color: var(--gp-text);
  font-weight: bold;
}

.wc-gp-tag {
  flex: none;
  padding: 0 0.4em;
  border: 1px solid var(--frost-edge, var(--gp-line));
  border-radius: 3px;
  background: rgb(0 0 0 / 0.3);
  color: var(--gp-label);
  font-size: 0.72em;
  line-height: 1.35;
  letter-spacing: 0.06em;
}

.wc-gp-where {
  display: flex;
  flex: 0 1 auto;
  align-items: center;
  gap: 0.3em;
  min-width: 0;
  overflow: hidden;
  color: var(--gp-label);
  font-size: 0.8em;
  text-overflow: ellipsis;
}

.wc-gp-where svg {
  flex: none;
  width: 1.05em;
  height: 1.05em;
}

.wc-gp-sts {
  display: flex;
  flex: none;
  align-items: center;
  gap: 2px;
}

.wc-gp-vr {
  width: 1px;
  height: calc(var(--gp-row) * 0.65);
  margin: 0 3px;
  background: var(--frost-edge, var(--gp-line));
}

.wc-gp-ic {
  position: relative;
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--gp-row);
  height: var(--gp-row);
  border-radius: 3px;
}

.wc-gp-ic:hover {
  background: var(--gp-hover);
}

.wc-gp-ic > .wc-gp-i {
  width: calc(var(--gp-row) * 0.78);
  height: calc(var(--gp-row) * 0.78);
}

.wc-gp-ic.has-ring > .wc-gp-i {
  width: calc(var(--gp-row) * 0.52);
  height: calc(var(--gp-row) * 0.52);
}

.wc-gp-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  /* The shared ring (icons.css): a dark recessed track, a dimmer unknown arc. */
  --ring-track: var(--gp-trk);
  --ring-unknown-opacity: 0.6;
}

.wc-gp-stime {
  margin: 0 2px 0 1px;
  font-size: 0.78em;
  font-variant-numeric: tabular-nums;
}

.wc-gp-more {
  padding-left: 2px;
  color: var(--gp-label);
  font-size: 0.75em;
}

/* The bars: three in a row under the name (a hover target a cell high). */
.wc-gp-bars {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(var(--cell-w, 9px) * 0.7);
  height: var(--gp-row);
  align-items: center;
}

.wc-gp-bar,
.wc-gp-fbar,
.wc-gp-sbar {
  display: flex;
  align-items: center;
  min-width: 0;
  height: 100%;
}

.wc-gp-trk {
  position: relative;
  display: flex;
  width: 100%;
  height: max(4px, calc(var(--gp-row) * 0.3));
  overflow: hidden;
  border-radius: 3px;
  background: var(--gp-trk);
  box-shadow: var(--gp-trk-edge);
}

/* The fill is as wide as its track and slides left by what is missing
 * (`--p`, 0–100): a transform, so a new value (and its transition) needs
 * no layout. The track clips it; its own rounded right end stays. */
.wc-gp-fill {
  flex: none;
  width: 100%;
  height: 100%;
  border-radius: 3px;
  /* Over the bar's colour (set inline as background-color). */
  background-image: var(--gp-gloss);
  transform: translateX(calc((var(--p, 0) - 100) * 1%));
  transition: transform 0.4s;
}

.wc-gp-row.is-away .wc-gp-name,
.wc-gp-row.is-away .wc-gp-bars,
.wc-gp-row.is-away .wc-gp-mini,
.wc-gp-row.is-away .wc-gp-mk {
  opacity: 0.5;
}

/* One line: marker, name, three mini bars, icons. */
.wc-gp-m1 {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(4em, 30%);
  align-items: center;
  gap: calc(var(--cell-w, 9px) * 0.7);
  height: var(--gp-row);
}

.wc-gp-mini {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 3px;
  height: 100%;
}

.wc-gp-mini .wc-gp-trk {
  height: max(3px, calc(var(--gp-row) * 0.24));
}

.wc-gp-m1 .wc-gp-sts {
  justify-content: flex-end;
  gap: 0;
}

.wc-gp-m1 .wc-gp-ic {
  width: calc(var(--gp-row) * 0.95);
}

.wc-gp-m1 .wc-gp-ic > .wc-gp-i {
  width: calc(var(--gp-row) * 0.7);
  height: calc(var(--gp-row) * 0.7);
}

.wc-gp-over {
  height: var(--gp-row);
  color: #d9a54a;
  font-size: 0.85em;
}

/* --------------------------------------------------------- fight zone */

.wc-gp-fight {
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--gp-row) * 2) minmax(0, 1fr);
  height: calc(var(--gp-row) * 3);
  /* Half a row of gap to the members (no divider; owner round 1). */
  margin-bottom: calc(var(--gp-row) * 0.5);
  /* A brighter card: the side tints (the tank gold, the opponent red) over
   * the frost, its rim lit. */
  --gp-sides: linear-gradient(90deg, rgb(232 195 90 / 0.07), transparent 45%, transparent 55%, rgb(255 77 77 / 0.08));
  border: 1px solid var(--frost-edge, var(--gp-line));
  border-radius: 5px;
  background: var(--gp-sides), var(--gp-card);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--lamp) 30%, transparent),
    0 1px 3px rgb(0 0 0 / 0.5);
}

.wc-gp[data-light] .wc-gp-fight {
  --gp-sides: linear-gradient(90deg, rgb(143 106 0 / 0.08), transparent 45%, transparent 55%, rgb(196 32 32 / 0.07));
}

.wc-gp-fs {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.wc-gp-ft {
  display: flex;
  align-items: center;
  gap: 0.4em;
  height: var(--gp-row);
  min-width: 0;
}

.wc-gp-fs.is-foe .wc-gp-ft {
  justify-content: flex-end;
}

.wc-gp-fn {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--gp-text);
  font-weight: bold;
}

.wc-gp-fn.is-foe {
  color: #ff9b8f;
}

.wc-gp[data-light] .wc-gp-fn.is-foe {
  color: #a01c1c;
}

.wc-gp-fbar {
  height: var(--gp-row);
}

.wc-gp-fbar .wc-gp-trk,
.wc-gp-fbar .wc-gp-fill {
  border-radius: 4px;
}

.wc-gp-fbar .wc-gp-trk {
  height: max(6px, calc(var(--gp-row) * 0.45));
}

/* You tank: the opponent alone fills the card (its bar from the left). */
.wc-gp-fight.is-solo {
  grid-template-columns: minmax(0, 1fr);
  padding: 0 0.3em;
  --gp-sides: linear-gradient(90deg, rgb(255 77 77 / 0.08), transparent 70%);
}

.wc-gp[data-light] .wc-gp-fight.is-solo {
  --gp-sides: linear-gradient(90deg, rgb(196 32 32 / 0.07), transparent 70%);
}

.wc-gp-fs.is-solo .wc-gp-ft {
  justify-content: flex-start;
}

.wc-gp-fs.is-solo .wc-gp-fsub.is-foe {
  text-align: left;
}

/* The opponent's bar fills from the right, toward the middle. */
/* The opponent's bar fills from the right. */
.wc-gp-fbar.is-foe .wc-gp-fill,
.wc-gp-sbar.is-foe .wc-gp-fill {
  transform: translateX(calc((100 - var(--p, 0)) * 1%));
}

.wc-gp-fbar.is-empty::after,
.wc-gp-sbar.is-empty::after {
  content: '';
  width: 100%;
  height: max(4px, calc(var(--gp-row) * 0.3));
  border-radius: 3px;
  background: var(--gp-trk);
  box-shadow: var(--gp-trk-edge);
}

.wc-gp-fsub {
  height: var(--gp-row);
  overflow: hidden;
  color: var(--gp-label);
  font-size: 0.8em;
  text-overflow: ellipsis;
}

.wc-gp-fsub.is-foe {
  text-align: right;
  color: #ff9b8f;
}

.wc-gp[data-light] .wc-gp-fsub.is-foe {
  color: #a01c1c;
}

.wc-gp-vs {
  display: flex;
  align-items: center;
  justify-content: center;
}

.wc-gp-vsm {
  display: flex;
  align-items: center;
  justify-content: center;
  width: calc(var(--gp-row) * 1.5);
  height: calc(var(--gp-row) * 1.5);
  box-sizing: border-box;
  border: 1px solid var(--frost-edge, var(--gp-line));
  border-radius: 50%;
  /* A small medallion: dark glass lit from above, its letters in the lamp. */
  background:
    radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--lamp) 30%, transparent), transparent 70%),
    rgb(0 0 0 / 0.4);
  color: color-mix(in srgb, var(--lamp) 60%, #ddd);
  font-family: "Cinzel", Georgia, "Times New Roman", serif;
  font-weight: 700;
  font-size: 0.68em;
  letter-spacing: 0.04em;
}

/* The one-line fight strip: a card like the fight zone's, a cell high. */
.wc-gp-fstrip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.4em;
  height: var(--gp-row);
  /* No divider (owner round 1): a faint tint tells it from the members. */
  --gp-sides: linear-gradient(90deg, rgb(232 195 90 / 0.07), transparent 45%, transparent 55%, rgb(255 77 77 / 0.08));
  border-radius: 3px;
  background: var(--gp-sides), var(--gp-card);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--lamp) 30%, transparent),
    inset 0 0 0 1px var(--frost-edge),
    0 1px 2px rgb(0 0 0 / 0.45);
}

.wc-gp[data-light] .wc-gp-fstrip {
  --gp-sides: linear-gradient(90deg, rgb(143 106 0 / 0.08), transparent 45%, transparent 55%, rgb(196 32 32 / 0.07));
}

/* You tank: the foe icon, its name, a full-width bar. */
.wc-gp-fstrip.is-solo {
  grid-template-columns: auto minmax(0, max-content) minmax(0, 1fr);
  --gp-sides: linear-gradient(90deg, rgb(255 77 77 / 0.08), transparent 70%);
}

.wc-gp[data-light] .wc-gp-fstrip.is-solo {
  --gp-sides: linear-gradient(90deg, rgb(196 32 32 / 0.07), transparent 70%);
}

.wc-gp-svs {
  color: var(--gp-mid);
  font-size: 0.7em;
}

/* A light pane (Paper, ADR 0123 "Paper"): the cards are raised paper (a
 * warm near-white, a faint rim and a soft warm shadow), the tracks the
 * pane's track darkened toward the metal's shadow, recessed with a white
 * lip, the fill's gloss softer. Static, as on a dark pane. */
.wc-gp[data-light] {
  --gp-card: color-mix(in srgb, #fffdf8 92%, var(--card-back, transparent));
  --gp-card-hover: color-mix(in srgb, #fff 100%, var(--card-back, transparent));
  --gp-card-edge:
    inset 0 0 0 1px rgb(60 40 10 / 0.05),
    0 1px 2px rgb(60 40 10 / 0.22),
    0 2px 5px rgb(60 40 10 / 0.08);
  --gp-trk: color-mix(in srgb, var(--gp-track) 75%, var(--iron-lo));
  --gp-trk-edge: inset 0 1px 2px rgb(0 0 0 / 0.3), 0 1px 0 rgb(255 255 255 / 0.9);
  --gp-gloss: linear-gradient(180deg, rgb(255 255 255 / 0.35), rgb(255 255 255 / 0) 55%, rgb(0 0 0 / 0.1));
}

.wc-gp[data-light] :is(.wc-gp-fight, .wc-gp-fstrip) {
  border-color: rgb(60 40 10 / 0.1);
  box-shadow:
    0 1px 2px rgb(60 40 10 / 0.25),
    0 3px 8px rgb(60 40 10 / 0.1);
}

/* The NPC tag: a small plate of the lit metal, its letters in the ink
 * (the label shade read 3.9:1 on the brass). */
.wc-gp[data-light] .wc-gp-tag {
  border-color: color-mix(in srgb, var(--iron-lo) 45%, transparent);
  background: var(--iron-hi);
  color: var(--ink, var(--gp-label));
}

/* The vs medallion: a small brass (pewter) coin, engraved. */
.wc-gp[data-light] .wc-gp-vsm {
  border-color: var(--engrave);
  background:
    radial-gradient(circle at 50% 30%, var(--iron-hi), transparent 75%),
    var(--iron);
  box-shadow: 0 1px 2px rgb(50 35 10 / 0.35);
  color: var(--ink);
  text-shadow: 0 1px 0 rgb(255 255 255 / 0.6);
}

/* Timers pane (src/panes/timers.ts, ADR 0122): DOM in the pane's font,
 * sizes in em of it. `--c` is a group's colour; `--tm-*` the pane shade
 * ramp's text and line colours and the side's ending-soon red (set by the
 * pane). The list scrolls natively by pixels above the indicator row
 * (ADR 0052).
 *
 * The lantern look (ADR 0123, stage 40b): a pill is a chip of frosted glass
 * catching the pane's lamp (`--lamp` at 8 %, layout.css) on `--card-back` (a
 * clear pane's backing), with an inner edge in its group's colour and a
 * lit top edge; a header is the name in bold over a rule that fades out in
 * the lamp's colour. The chip's paint is static: the tick changes only its
 * fill's `--p` and its time's text. */
.wc-tm {
  position: absolute;
  inset: 0;
  /* Fills the content box, which clips: a change in here never lays out
   * or repaints anything outside it. */
  contain: strict;
  display: flex;
  flex-direction: column;
  white-space: nowrap;
  color: var(--tm-fg);
  --tm-tint: 28%;
  --tm-edge: 45%;
  /* One flat colour (a gradient here cost about half a millisecond a
   * frame in Firefox with two dozen chips): the lamp's frost on the card
   * backing. */
  --tm-card: color-mix(in srgb, var(--lamp) 8%, var(--card-back, transparent));
  --tm-lit: inset 0 1px 0 color-mix(in srgb, var(--lamp) 22%, transparent);
  --tm-drop: 0 1px 2px rgb(0 0 0 / 0.4);
  --tm-head: color-mix(in srgb, var(--lamp) 30%, var(--tm-fg));
  --tm-rule: linear-gradient(90deg, color-mix(in srgb, var(--lamp) 38%, transparent), transparent 85%);
}

/* A light pane (Paper, ADR 0123 "Paper"): a chip is raised paper (a warm
 * near-white, no lit edge, a soft warm shadow), the header in the pane's
 * dark ink (layout.css `--ink`) over a rule in the metal's shadow. */
.wc-tm[data-light] {
  --tm-tint: 22%;
  --tm-edge: 50%;
  --tm-card: color-mix(in srgb, #fffdf8 92%, var(--card-back, transparent));
  --tm-lit: 0 0 transparent;
  --tm-drop: 0 1px 2px rgb(60 40 10 / 0.22);
  --tm-head: var(--ink, var(--tm-fg));
  --tm-rule: linear-gradient(90deg, color-mix(in srgb, var(--iron-lo) 45%, transparent), transparent 85%);
  /* The time halfway from the label shade to the text: the label shade
   * alone read 3.6:1 over a chip's tinted fill. */
  --tm-time: color-mix(in srgb, var(--tm-dim) 50%, var(--tm-fg));
}

.wc-tm-scroll {
  position: relative;
  flex: 1 1 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  overflow-anchor: none;
  scrollbar-width: none;
}

.wc-tm-list {
  padding: 0.15em 0.25em 0.3em;
}

.wc-tm svg {
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* A group: header (icon, name, Herblore's +, rule), then its items. */
.wc-tm-g + .wc-tm-g {
  margin-top: 0.35em;
}

/* The header in the pane's own (mono) font, bold, at the items' size; its
 * box is as high as before (1.08 of the pane's em), so the list scrolls
 * the same. */
.wc-tm-h {
  display: flex;
  align-items: center;
  gap: 0.45em;
  height: 1.27em;
  font-size: 0.85em;
  font-weight: bold;
  letter-spacing: 0.03em;
  color: var(--tm-head);
}

.wc-tm-h[hidden] {
  display: none;
}

.wc-tm-hi {
  flex: none;
  width: 1.06em;
  height: 1.06em;
  color: var(--c);
  /* Headers do not change on the tick: a soft glow in the group's colour. */
  filter: drop-shadow(0 0 2px color-mix(in srgb, var(--c) 70%, transparent));
}

.wc-tm[data-light] .wc-tm-hi {
  filter: none;
}

.wc-tm-hln {
  flex: 1 1 auto;
  height: 1px;
  margin-left: 0.2em;
  background: var(--tm-rule);
}

/* Herblore's + (ADR 0122 addendum): beside the name, opens the herb menu. */
.wc-tm .wc-tm-add {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.5em;
  height: 1.5em;
  margin-left: -0.2em;
  border-radius: 0.3em;
  color: var(--c);
  font-size: 1.06em;
  font-weight: bold;
  letter-spacing: 0;
  line-height: 1;
}

.wc-tm .wc-tm-add:hover,
.wc-tm .wc-tm-add[aria-expanded] {
  background: color-mix(in srgb, var(--c) 18%, transparent);
}

.wc-tm .wc-tm-add[hidden] {
  display: none;
}

.wc-tm-items {
  font-size: 0.85em;
}

.wc-tm-items.is-flow {
  display: flex;
  flex-wrap: wrap;
}

.wc-tm-items.is-grid {
  display: grid;
}

.wc-tm-items.is-flow > * {
  flex: 0 1 auto;
  max-width: 100%;
}

.wc-tm[data-style='bars'] .wc-tm-items {
  gap: 0.3em;
}

.wc-tm[data-style='circles'] .wc-tm-items {
  gap: 0.1em 0.8em;
}

/* Bars: a chip whose own fill drains right to left under the name and
 * time: frosted glass, an edge in the group's colour, lit from above. */
.wc-tm-chip {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 0.45em;
  min-width: 0;
  height: 1.7em;
  padding: 0 0.6em 0 0.5em;
  border: 1px solid color-mix(in srgb, var(--c) var(--tm-edge), transparent);
  border-radius: 0.3em;
  background: var(--tm-card);
  box-shadow: var(--tm-lit), var(--tm-drop);
}

/* The fill: a childless element over the chip's padding box with its
 * rounding, the group's tint up to `--p` (0–100) and clear after it. A new
 * value restyles and repaints this element only (no layout, no clip; `--p`
 * here has no descendants to inherit it); the pulse fades it. One flat
 * tint with a hard stop: a ramp (faint to strong, as in the mockup) made
 * Firefox redraw a real gradient for every chip on every tick, about
 * 1.5 ms a tick with two dozen chips (ADR 0123 "Built (stage 40b)"). */
.wc-tm-fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--c) var(--tm-tint), transparent) calc(var(--p, 0) * 1%), transparent 0);
  pointer-events: none;
}

.wc-tm-ic {
  position: relative;
  flex: none;
  width: 0.95em;
  height: 0.95em;
  color: var(--c);
}

.wc-tm-n {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Sideways only, so an underscore under the baseline is not cut (as .wc-prow). */
@supports (overflow: clip) {
  .wc-tm-n {
    overflow-x: clip;
    overflow-y: visible;
  }
}

.wc-tm-t {
  position: relative;
  flex: none;
  color: var(--tm-time, var(--tm-dim));
  font-variant-numeric: tabular-nums;
}

.wc-tm-t[hidden] {
  display: none;
}

.wc-tm-chip.is-untimed {
  border-style: dashed;
  border-color: color-mix(in srgb, var(--tm-dim) 80%, transparent);
  background: var(--card-back, transparent);
  box-shadow: none;
}

.wc-tm-chip.is-untimed .wc-tm-n,
.wc-tm-rc.is-untimed .wc-tm-n {
  color: var(--tm-dim);
}

.wc-tm-chip.is-charm {
  background: color-mix(in srgb, var(--lamp) 4%, var(--card-back, transparent));
}

/* Circles: an 18 px ring (its arc drains), the icon inside, name and time beside. */
.wc-tm-rc {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 0.45em;
  min-width: 0;
  height: 1.55em;
  padding: 0 0.25em;
  border-radius: 0.3em;
}

.wc-tm-rw {
  position: relative;
  flex: none;
  width: 1.4em;
  height: 1.4em;
}

.wc-tm-ring {
  width: 100%;
  height: 100%;
  /* The shared ring (icons.css) in the group's colour, on a dark track. */
  --ring-track: rgb(0 0 0 / 0.5);
  --ring-color: var(--c);
  --ring-w: 2.6;
  --ring-unknown: var(--tm-dim);
}

.wc-tm .wc-tm-ii {
  position: absolute;
  left: 30%;
  top: 30%;
  width: 40%;
  height: 40%;
  color: var(--c);
  stroke-width: 2.6;
}

/* Ending soon: the colour stays; the time turns red and bold with a soft
 * glow (only these few seconds of a few items), or the fill pulses. */
.is-text > .wc-tm-t {
  color: var(--tm-ending);
  font-weight: bold;
  text-shadow: 0 0 5px color-mix(in srgb, var(--tm-ending) 45%, transparent);
}

.wc-tm[data-light] .is-text > .wc-tm-t {
  text-shadow: none;
}

@keyframes wc-tm-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

.is-pulse .wc-tm-fill,
.is-pulse .wc-ring-arc {
  animation: wc-tm-pulse 1.4s ease-in-out infinite;
}

/* The icon pulses too, with a soft glow in its own colour: a long timer's
 * remaining fill is a sliver, the icon is always there (owner). */
@keyframes wc-tm-pulse-icon {
  0%,
  100% {
    opacity: 1;
    filter: drop-shadow(0 0 0.18em var(--c));
  }
  50% {
    opacity: 0.35;
    filter: none;
  }
}

.is-pulse .wc-tm-ic,
.is-pulse .wc-tm-ii {
  animation: wc-tm-pulse-icon 1.4s ease-in-out infinite;
}

/* The charm ×, and buttons in the pane (they keep the focus in the input). */
.wc-tm button {
  all: unset;
  cursor: pointer;
  user-select: none;
}

.wc-tm .wc-tm-x {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.2em;
  height: 1.2em;
  margin-right: -0.35em;
  border-radius: 0.2em;
  color: var(--tm-dim);
}

.wc-tm .wc-tm-x:hover {
  background: color-mix(in srgb, var(--tm-fg) 12%, transparent);
  color: #e88888;
}

.wc-tm-x svg {
  width: 0.7em;
  height: 0.7em;
}

/* A herblore's ×: only on hover, in place of its time. */
.wc-tm-rc.has-herbx {
  position: relative;
}

.wc-tm .wc-tm-x.is-herb {
  position: absolute;
  top: 50%;
  right: 0.35em;
  margin: -0.6em 0 0;
  visibility: hidden;
}

.has-herbx:hover > .wc-tm-x.is-herb {
  visibility: visible;
}

.has-herbx:hover > .wc-tm-t {
  visibility: hidden;
}

/* The Herblore + menu (timers.ts HerbMenu): a small card in the menu
 * surface colours, fixed under the +, one row per herb. */
.wc-tm-menu {
  position: fixed;
  z-index: 270;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-width: 12em;
  max-height: min(60vh, 24em);
  overflow-y: auto;
  padding: 4px;
  border: 1px solid var(--sf-border, #2c2c2c);
  border-radius: 5px;
  background: var(--sf-bg, #0a0a0a);
  box-shadow: var(--sf-shadow, 0 10px 26px rgba(0, 0, 0, 0.75));
  color: var(--sf-fg, #c4c4c4);
  font-family: var(--font-mono);
  font-size: calc(var(--font-size, 15px) * 0.82);
  white-space: nowrap;
}

.wc-tm-menu[hidden] {
  display: none;
}

.wc-tm-menu .wc-tm-mi {
  all: unset;
  display: flex;
  align-items: center;
  gap: 0.6em;
  padding: 0.2em 0.6em 0.2em 0.4em;
  border-radius: 3px;
  cursor: pointer;
  user-select: none;
}

.wc-tm-menu .wc-tm-mi:hover {
  background: var(--sf-hover, #171717);
  color: var(--sf-hot, #ebebeb);
}

.wc-tm-menu .wc-tm-mi.is-on {
  cursor: default;
  color: var(--sf-faint, #5b5b5b);
}

.wc-tm-menu .wc-tm-mi.is-on:hover {
  background: none;
  color: var(--sf-faint, #5b5b5b);
}

.wc-tm-mm {
  width: 1em;
  text-align: center;
  font-weight: bold;
  color: var(--sf-gold, #d4a04e);
}

/* Measures the items' character width (the room for blind names). */
.wc-tm-probe {
  position: absolute;
  left: 0;
  top: 0;
  font-size: 0.85em;
  visibility: hidden;
  pointer-events: none;
}

.wc-tm-more {
  flex: none;
  height: var(--cell-h);
  line-height: var(--cell-h);
  overflow: hidden;
  padding: 0 0.25em;
  color: #d4a04e;
  font-style: italic;
}

.wc-tm-more[hidden] {
  display: none;
}

.wc-tm-more[data-up] {
  cursor: pointer;
  user-select: none;
}

.wc-tm-scroll::-webkit-scrollbar {
  display: none;
}

.wc-tm[data-light] .wc-tm-ring {
  --ring-track: var(--tm-line);
}

/* The menu bar and its popups (src/menubar, ADR 0099): the ghost look of
 * the approved 30a mockups (notes/research/fixed-menu-mockups/30a-1, -2,
 * -4). The bar sits on the cell grid: every part is a whole or half cell
 * wide and the bar's width is set to whole cells by menubar.ts. Popups and
 * the tooltip are menu surfaces (`--sf-*`, ADR 0116): a panel derived from
 * the terminal background, a light card on Paper, a tinted panel on the
 * dark themes. The bar's own greys come from the same tokens; the
 * translucent washes and the clock's hues flip on a light terminal
 * (`data-light`). Sizes scale with the terminal font (the mockups' px at a
 * 15 px font). */

.wc-menubar {
  --mb-ic: var(--sf-icon);
  --mb-hot: var(--sf-hot);
  --mb-hover-bg: rgba(255, 255, 255, 0.07);
  --mb-sep: var(--sf-border);
  --mb-exit: var(--sf-danger);
  --mb-disc: var(--sf-danger);
  --mb-rc-fg: var(--sf-hot);
  --mb-rc-bd: color-mix(in srgb, var(--sf-border) 70%, var(--sf-border-hot));
  --mb-rc-bg: rgba(255, 255, 255, 0.05);
  --mb-rc-bd-hot: var(--sf-border-hot);
  --mb-rc-bg-hot: rgba(255, 255, 255, 0.1);
  --mb-k: var(--sf-dim);
  /* The clock's ring and glyph (stage 31a). */
  --mb-clk-day-ring: #d9a54a;
  --mb-clk-sun: #e0a336;
  --mb-clk-night: #5b93d6;
  --mb-clk-slot: var(--sf-border);
  /* Icon size: 13 px in a 17 px cell. */
  --mb-isz: calc(var(--cell-h) * 0.76);
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  height: var(--cell-h);
  white-space: pre;
  user-select: none;
  -webkit-user-select: none;
}

/* The bar sits on the page, not on a panel: on a light page its washes
 * and rules are translucent ink, and the icons one step darker. */
.wc-menubar[data-light] {
  --mb-ic: var(--sf-dim);
  --mb-hover-bg: rgba(0, 0, 0, 0.08);
  --mb-sep: rgba(0, 0, 0, 0.2);
  --mb-rc-bd: rgba(0, 0, 0, 0.28);
  --mb-rc-bg: rgba(0, 0, 0, 0.04);
  --mb-rc-bd-hot: rgba(0, 0, 0, 0.5);
  --mb-rc-bg-hot: rgba(0, 0, 0, 0.08);
  --mb-clk-day-ring: #8f5f0c;
  --mb-clk-sun: #94600a;
  --mb-clk-night: #2a64a8;
  --mb-clk-slot: rgba(0, 0, 0, 0.22);
}

.wc-mb-bar {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
  height: var(--cell-h);
  overflow: hidden;
}

/* The clock (src/menubar/bar-clock.ts, stage 31a): a gutter, then the
 * ring in a 2-cell slot, as tall as the cell, and while synced to the hour
 * only a grey `~` in one more cell. The width (3 or 4 cells) is set by
 * bar-clock.ts. Not synced: an empty slot, a faint dashed circle on hover. */
.wc-mb-clock {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: var(--cell-h);
  cursor: default;
}

.wc-mb-ring {
  display: block;
  flex: 0 0 calc(2 * var(--cell-w));
  width: calc(2 * var(--cell-w));
  height: var(--cell-h);
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.wc-mb-ring-arc {
  stroke-width: 1.35;
}

.wc-mb-clock[data-period="day"] .wc-mb-ring-arc {
  stroke: var(--mb-clk-day-ring);
}

.wc-mb-clock[data-period="day"] .wc-mb-ring-glyph {
  stroke: var(--mb-clk-sun);
  stroke-width: 1.5;
}

.wc-mb-clock[data-period="night"] .wc-mb-ring-arc {
  stroke: var(--mb-clk-night);
}

.wc-mb-clock[data-period="night"] .wc-mb-ring-glyph {
  fill: var(--mb-clk-night);
}

.wc-mb-ring-slot {
  visibility: hidden;
  stroke: var(--mb-clk-slot);
  stroke-width: 1.35;
  stroke-dasharray: 2 2.2;
}

.wc-mb-clock[data-sync="none"]:hover .wc-mb-ring-slot {
  visibility: visible;
}

.wc-mb-tilde {
  display: block;
  flex: 0 0 var(--cell-w);
  width: var(--cell-w);
  height: var(--cell-h);
  font-size: calc(var(--font-size) * 0.87);
  line-height: var(--cell-h);
  text-align: center;
  color: var(--mb-ic);
  /* Optically: a little closer to the ring, and centred on it (the glyph's
   * ink sits below the cell's middle). */
  position: relative;
  left: calc(var(--cell-w) * -0.1);
  top: calc(var(--cell-h) * -0.04);
}

.wc-mb-tilde[hidden] {
  display: none;
}

/* The link dot: one cell, shown only when the link deviates. */
.wc-mb-dotw {
  display: flex;
  flex: 0 0 var(--cell-w);
  align-items: center;
  justify-content: center;
  width: var(--cell-w);
  height: var(--cell-h);
}

.wc-mb-dot {
  display: block;
  width: calc(var(--cell-h) * 0.3);
  height: calc(var(--cell-h) * 0.3);
  border-radius: 50%;
  background: var(--sf-off);
}

.wc-mb-dot[data-state="lagging"] {
  background: #ffd75f;
}

.wc-mb-dot[data-state="broken"] {
  background: #ff5f5f;
}

.wc-mb-dot[hidden] {
  display: none;
}

.wc-mb-sep {
  position: relative;
  flex: 0 0 var(--cell-w);
  width: var(--cell-w);
  height: var(--cell-h);
}

.wc-mb-sep::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1px;
  height: calc(var(--cell-h) * 0.65);
  transform: translate(-50%, -50%);
  background: var(--mb-sep);
}

.wc-mb {
  all: unset;
  box-sizing: border-box;
  display: flex;
  flex: 0 0 calc(2.5 * var(--cell-w));
  align-items: center;
  justify-content: center;
  width: calc(2.5 * var(--cell-w));
  height: var(--cell-h);
  border-radius: 3px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.wc-mb-ic {
  width: var(--mb-isz);
  height: var(--mb-isz);
  fill: none;
  stroke: var(--mb-ic);
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.wc-mb:hover,
.wc-mb.is-open {
  background: var(--mb-hover-bg);
}

.wc-mb:hover .wc-mb-ic,
.wc-mb.is-open .wc-mb-ic {
  stroke: var(--mb-hot);
}

.wc-mb-exit:hover .wc-mb-ic,
.wc-mb-exit.is-open .wc-mb-ic {
  stroke: var(--mb-exit);
}

.wc-mb:focus-visible {
  outline: 1px solid var(--sf-border-hot);
}

/* The Disconnected notice (ADR 0100), left of the clock. */
.wc-mb-disc {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  height: var(--cell-h);
}

.wc-mb-disc[hidden] {
  display: none;
}

.wc-mb-disc-t {
  margin-right: var(--cell-w);
  color: var(--mb-disc);
}

.wc-mb-rc {
  all: unset;
  box-sizing: border-box;
  width: calc(17 * var(--cell-w));
  height: calc(var(--cell-h) - 2px);
  margin-right: var(--cell-w);
  border: 1px solid var(--mb-rc-bd);
  border-radius: 3px;
  background: var(--mb-rc-bg);
  color: var(--mb-rc-fg);
  font: inherit;
  letter-spacing: inherit;
  line-height: calc(var(--cell-h) - 4px);
  text-align: center;
  white-space: pre;
  cursor: pointer;
}

.wc-mb-rc:hover {
  border-color: var(--mb-rc-bd-hot);
  background: var(--mb-rc-bg-hot);
}

.wc-mb-rc:focus-visible {
  outline: 1px solid var(--sf-border-hot);
}

.wc-mb-k {
  color: var(--mb-k);
}

/* ------------------------------------------------------------- tooltip */

.wc-mb-tip {
  position: fixed;
  z-index: 270;
  box-sizing: border-box;
  padding: 0 5px;
  border: 1px solid var(--sf-border);
  border-radius: 3px;
  background: var(--sf-raised);
  box-shadow: var(--sf-shadow);
  color: var(--sf-hot);
  font-family: var(--font-mono);
  font-size: calc(var(--font-size) * 0.72);
  font-weight: normal;
  line-height: 1.4;
  letter-spacing: normal;
  white-space: nowrap;
  pointer-events: none;
}

.wc-mb-tip[hidden] {
  display: none;
}

/* -------------------------------------------------------------- popups */

.wc-pop {
  position: fixed;
  z-index: 260;
  box-sizing: border-box;
  overflow: auto;
  border: 1px solid var(--sf-border);
  border-radius: 5px;
  background: var(--sf-bg);
  box-shadow: var(--sf-shadow);
  color: var(--sf-fg);
  color-scheme: var(--sf-scheme);
  font-family: var(--font-mono);
  /* 13 px at a 15 px font. */
  font-size: calc(var(--font-size) * 0.867);
  font-weight: normal;
  line-height: 1.23;
  letter-spacing: normal;
  white-space: normal;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  scrollbar-width: thin;
}

.wc-pop button {
  all: unset;
  box-sizing: border-box;
  cursor: pointer;
}

.wc-pop button[hidden] {
  display: none;
}

.wc-pop button:focus-visible {
  outline: 1px solid var(--sf-focus);
}

/* Opened or pressed by the mouse: no focus ring until a key is used (ADR 0108). */
.wc-pop[data-pointer] :focus-visible {
  outline: none;
}

.wc-pop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 2.3em;
  padding: 0 0.46em 0 0.92em;
  border-bottom: 1px solid var(--sf-line);
}

.wc-pop-title {
  color: var(--sf-dim);
  font-size: 0.846em;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wc-pop .wc-pop-x {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.7em;
  height: 1.7em;
  border-radius: 3px;
}

.wc-pop-x-svg {
  width: 0.846em;
  height: 0.846em;
  fill: none;
  stroke: var(--sf-icon);
  stroke-width: 1.8;
  stroke-linecap: round;
}

.wc-pop .wc-pop-x:hover {
  background: var(--sf-hover);
}

.wc-pop-x:hover .wc-pop-x-svg {
  stroke: var(--sf-hot);
}

.wc-pop-panes {
  width: 20.3em;
}

.wc-pop-list {
  padding: 0.3em 0;
}

.wc-pop-sub {
  padding: 0.73em 1.09em 0.27em;
  color: var(--sf-faint);
  font-size: 0.846em;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.wc-pop .wc-pop-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 2em;
  padding: 0 0.92em;
}

.wc-pop .wc-pop-row:hover,
.wc-pop .wc-pop-row:focus-visible {
  outline: none;
  background: var(--sf-hover);
}

.wc-pop[data-pointer] .wc-pop-row:focus-visible:not(:hover) {
  background: none;
}

.wc-pop-lb {
  overflow: hidden;
  margin-right: 0.6em;
  color: var(--sf-fg);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wc-pop-lb.is-off {
  color: var(--sf-faint);
}

.wc-pop-sc {
  color: var(--sf-faint);
}

.wc-pop-tg {
  position: relative;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: 2em;
  height: 1.077em;
  border: 1px solid var(--sf-border);
  border-radius: 0.54em;
  background: var(--sf-field);
}

.wc-pop-tg i {
  position: absolute;
  top: 0.154em;
  left: 0.154em;
  width: 0.615em;
  height: 0.615em;
  border-radius: 50%;
  background: var(--sf-off);
}

.wc-pop-tg.is-on {
  border-color: var(--sf-on-track);
  background: var(--sf-on-track);
}

.wc-pop-tg.is-on i {
  left: 1.077em;
  background: var(--sf-on-knob);
}

.wc-pop-foot {
  display: flex;
  align-items: center;
  gap: 0.62em;
  min-height: 2em;
  padding: 0.62em 0.92em 0.77em;
  border-top: 1px solid var(--sf-line);
}

.wc-pop .wc-pop-btn {
  height: 1.69em;
  padding: 0 0.69em;
  border: 1px solid var(--sf-border);
  border-radius: 3px;
  color: var(--sf-dim);
  line-height: calc(1.69em - 2px);
}

.wc-pop .wc-pop-btn:hover {
  border-color: var(--sf-border-hot);
  background: var(--sf-hover);
  color: var(--sf-hot);
}

.wc-pop .wc-pop-btn.is-danger {
  border-color: var(--sf-danger-border);
  color: var(--sf-danger);
}

.wc-pop .wc-pop-btn.is-danger:hover {
  border-color: var(--sf-danger);
  background: var(--sf-danger-hover);
  color: var(--sf-danger);
}

.wc-pop-k {
  margin-left: 0.46em;
  color: var(--sf-faint);
}

.wc-pop-btn.is-danger .wc-pop-k {
  color: var(--sf-danger-border);
}

.wc-pop-q {
  flex: 1;
  color: var(--sf-fg);
}

/* Exit (mockup 30a-4). */
.wc-pop-exit {
  width: 21.5em;
  padding: 1.08em 1.08em 0.92em;
}

.wc-pop-ask {
  color: var(--sf-hot);
  font-size: 1.077em;
}

/* Unsaved changes in an open window (ADR 0103). */
.wc-pop-warn {
  margin-top: 0.6em;
  color: var(--sf-warn);
  font-size: 0.846em;
}

.wc-pop-note {
  margin-top: 1.1em;
  color: var(--sf-faint);
  font-size: 0.846em;
}

.wc-pop-stars {
  display: flex;
  gap: 2px;
  margin-top: 0.3em;
}

.wc-pop .wc-pop-star {
  width: 1.1em;
  color: var(--sf-off);
  font-size: 1.54em;
  line-height: 1.2;
  text-align: center;
}

.wc-pop .wc-pop-star.is-on {
  color: var(--sf-gold);
}

.wc-pop .wc-pop-star:hover {
  color: color-mix(in srgb, var(--sf-gold) 70%, var(--sf-hot));
}

.wc-pop .wc-pop-clear {
  align-self: center;
  margin-left: 0.62em;
  color: var(--sf-faint);
  font-size: 0.846em;
}

.wc-pop .wc-pop-clear:hover {
  color: var(--sf-fg);
}

.wc-pop-btns {
  display: flex;
  justify-content: flex-end;
  gap: 0.62em;
  margin-top: 1.23em;
}

.wc-pop-exit .wc-pop-btn {
  height: 1.85em;
  padding: 0 0.77em;
  line-height: calc(1.85em - 2px);
}

